/* 2018年10月30日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h30-20181030-9","dateIso":"2018-10-30","title":"2018年10月30日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4956#one","fetchedAt":"2026-08-14","characters":81611,"voices":[{"i":1,"speaker":"塚本委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日の予定ですが、昨日の委員会で所管質問の項目が新たに追加となりましたことから、皆様の机上に審査・調査予定表を配付しております。\nそれでは、改めまして、お手元の審査・調査予定表のとおり、報告事項、所管事務調査、その他と進めてまいります。\n本日も効率的な委員会運営にご協力をよろしくお願いいたします。\n────────────────────────────────────────────\n１ 報告事項\n(1) 平成３０年度移動教室実施結果について"},{"i":2,"speaker":"塚本委員長","text":"初めに、予定表１、報告事項を聴取いたします。\n(1)平成３０年度移動教室実施結果についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":3,"speaker":"篠田学務課長","text":"それでは、平成３０年度移動教室実施結果についてご報告させていただきます。お手元の資料をご覧ください。\n移動教室につきましては、教育課程の一環といたしまして、自然の中での体験学習や歴史に関する学習等を通じ、集団生活における規律や連帯感等を養うことを目的に実施してございます。それでは、１番の「小学校・義務教育学校（前期課程）移動教室」でございます。宿泊先につきましては、例年どおり日光の光林荘を利用しております。日程が２泊３日で、６年生と特別支援学級の３年生から６年生を対象としてございます。\n各学校の日程でございますけれども、資料をおめくりいただきまして別紙１をご覧ください。５月９日から９月２７日までの日程で、夏季休業期間を除きまして実施してございます。下のほう、小計欄でございますけれども、児童が２,４２６名、教員が２４２名、合計２,６６８名が参加いたしました。\n次に中学校でございます。恐れ入りますが１ページ目にお戻りください。２番の「中学校・義務教育学校（後期課程）移動教室」でございます。中学校の移動教室につきましては、昨年から全校が磐梯高原に戻ってきております。本年度も全校、磐梯高原で実施いたしました。日程につきましては２泊３日で、対象は７年生と特別支援学級の７・８・９年生となってございます。\n中学校の移動教室の内訳でございます。２枚おめくりいただきまして別紙２をご覧ください。こちらは５月２３日から９月１９日までの日程で実施いたしまして、生徒の数が１,５８４名、教員が１４１名の、合計１,７２５名が参加してございます。一番下の欄の前年度増減で見ていただきますと、生徒の数は、前年度に比べ６０名ほど減ってございます。これは、７年生全体の数が７８名ほど減っている関係で、参加者も減っているということでございます。なお、小学校、中学校、義務教育学校、全校ですが、今年度、大きな事故もなく、全校無事に終了してございます。"},{"i":4,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":5,"speaker":"飯沼委員","text":"事故もなく終了したということで大変よかったと思うのですが、１つ、ざっくりでいいのですが、小学校と中学校の移動教室の中身を教えてほしいのと、参加できなかった児童・生徒の方がどのぐらいいるのかと、その理由がわかったら教えていただきたいと思います。"},{"i":6,"speaker":"篠田学務課長","text":"まず、移動教室の大まかな中身でございますけれども、小学校・義務教育学校につきましては、基本的には、日光の歴史や現地のさまざまな史跡等を事前に勉強いたしまして、それを確認するといったことと、それから現地の自然に触れ合う。蚕や戦場ヶ原でハイキング等を行うということで、見学先としましては、東照宮や華厳の滝、中禅寺湖、それから戦場ヶ原のハイキング、そのほか、それぞれの学校で日光の江戸村に行ってみたり、足尾銅山を見学をしたりといったことをしてございます。\n中学校でございますけれども、こちらは磐梯高原ということで、主な体験としては、猪苗代ですとか会津藩校、野口英世記念館等の見学ですとか、あるいは登山、ハイキングということで、雄国山等のハイキング等を実施してございます。\nそれから不参加の状況でございますけれども、今回、全体では、小学校・義務教育学校（前期課程）で在籍者が２,４７５名おりますけれども、不参加者が４９名でございました。小学校のほうの不参加の状態は、ほとんどが当日等の体調等の問題と、あるいは若干、もともと不登校のお子さんがいらっしゃるということでございます。一部、イスラムの方などは宗教上の理由で神社仏閣に参拝ができないということで、ご欠席された方がいらしたというのを聞いております。それから中学のほうが、在籍者が全部で１,６１７名でございますけれども、不参加のお子さんが３３名おられます。基本的には小学校と同じように、体調等の不良ですとか不登校ということと、やはりイスラムの方で、逆に今度、お食事、ハラル限定の方がいらっしゃって、それが原因となりまして不参加ということをお聞きしてございます。"},{"i":7,"speaker":"飯沼委員","text":"参加できなかった児童・生徒の方への後のフォローなど、何か具体的にされていることがあったら教えてください。"},{"i":8,"speaker":"篠田学務課長","text":"それぞれの学校で、参加できなかったお子さんへのフォローはされているとお聞きしています。例えば、お子様同士で現地の思い出、状況を話し合ったり、場合によってはお土産などを買われていったりされる方もいらっしゃるとはお聞きしています。また教師も寂しい思いをしないような形でフォローしていると聞いております。"},{"i":9,"speaker":"飯沼委員","text":"ありがとうございます。"},{"i":10,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":11,"speaker":"石田（し）委員","text":"２点お伺いします。１点目が、参加されているお子様の中で、いわゆる財政的な支援を受けている生徒はどのぐらいいるのか、わかる範囲で教えていただきたいです。それと、もう一点は携帯電話なのですが、移動教室等で外に行かれる際に、携帯電話の取り扱いはどのようになっているのか教えてください。"},{"i":12,"speaker":"篠田学務課長","text":"それでは、財政的支援のほうをお答えいたします。全体の数、基本的には、就学援助の方等が該当してくると思われるのですけれども、学年に関して何人かというのは、今、手元には数字はないのですけれども、大体、一般的な就学援助の方は、今、３割程度いらっしゃいます。移動教室に関しましては、小学校で５,７００円、中学校で６,３００円と就学援助が支給されますので、そういった方々がやはり該当するのかなということでございます。"},{"i":13,"speaker":"大関教育総合支援センター長","text":"携帯電話等、連絡手段につきましては、基本的にトランシーバー等の貸し出しと、それから必要に応じて、貸し出しのＰＨＳ・携帯等は対応しますが、ただ、管理職が持っておりますので、子どもたちに具体的に何か持たせるなどというケースはこれまでございません。"},{"i":14,"speaker":"石田（し）委員","text":"携帯電話のほうですが、子どもたちが持っているものを持っていかせないということをしているのか、ある程度、そこは許してやっているのか、その辺をお聞かせください。"},{"i":15,"speaker":"大関教育総合支援センター長","text":"日常の教育活動の一環として行っておりますので、私物の携帯電話の持参・持ち込みは禁じております。"},{"i":16,"speaker":"石田（し）委員","text":"わかりました。ありがとうございます。"},{"i":17,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":18,"speaker":"高橋（し）委員","text":"特別支援学級の実施についてお尋ねしたいのですけれども、教員の数はここに出ているのですけども、それ以外に、付き添いといいますか、一緒に行かれた方というのは、どのような立場の方がどんな基準で一緒に行かれるのか、もし行っていないなら、教員だけということで。小学校、中学校ともに教えていただきたいのが１つ。\nもう一つは、マイスクールの子どもたちが、こういう形ではなくて宿泊体験といいますか、それをしていると思うのですが、時期的にここと一緒ではなくて、また学年全部で行くのかもしれませんけれども、マイスクールのほうの宿泊についてご説明いただきたいと思います。"},{"i":19,"speaker":"大関教育総合支援センター長","text":"教員以外の支援者でございますが、日常、普段学校にＮＰＯから支援が入っており、基本的には同じ方になるのが一番望ましいというふうに教育総合支援センターで支援しておりますので、実際に移動教室の方にも行っていただいております。これは教育総合支援センターのほうの予算の配置の範囲内で行っております。学校の実態に応じ、通常の担任以外に養護教諭が行っていたりと、教員のほうがまず手厚くなって、それ以外にさらに足りない部分をということで支援員が行く、お子さんの実態に応じながら支援しているところでございます。ちょっと今、具体的な数が手元にございませんが、それは学校のほうで配置できております。\nそれから、適応指導教室、マイスクール八潮のお子さんたちは、例年、秋の時期に、やはり日光に行っておりまして、そちらはマイスクールの指導員以外に指導主事も一緒に参加して、日ごろの適応指導教室などとはまた違った様子などを見ながら、家庭との共有の学習材料の一つとしているところでございます。"},{"i":20,"speaker":"高橋（し）委員","text":"特別支援学級のほうで行くときは、やはり通常の学校の生活の中で支援員の方がついていただいていることによって、なかなか厳しい面もあるのでしょうけれども、上手く運営されているということがあるので、ぜひ今の体制、あるいは、先生方で足りるからというのではなくて、支援員の方を必ずつけていただいて、特に一日中歩いたり、いろいろ大変なこともあるので、今やられているのですけれども、ぜひさらに充実していただきたいと思います。\nマイスクールのほうは、宿泊体験も彼らができるということで、非常にいいことだと思います。こちらも続けていただきたいのですが、またその一方で、事故などないように十分注意していただきたいと思います。"},{"i":21,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":22,"speaker":"つる委員","text":"別紙２にもあるので確認ですが、移動は、バスでするということでよろしいのでしょうか。"},{"i":23,"speaker":"篠田学務課長","text":"移動教室の移動は全てバスを使ってございます。"},{"i":24,"speaker":"つる委員","text":"では、関連してということになると思うのですが、２７日のＮＨＫの報道をちょうど拝見しまして、大会組織委員会ですか、２年後の東京オリンピックでのバス使用に関してということで報道があって、学務課長もそこに出演されていました。ちょうど偶然なのですけれど見まして、お聞きしたいのです。移動教室なので、移動教室自体の時期というのは、さほど直接的な影響はないとは理解するのですが、ただ、林間学園については、まさに時期が重なるということで、そういう要請があるという中で、報道では情報収集という表現でしたが、まさに２年後ですけれども、どういう手だてが考えられるのかという現状のところを教えていただきたいのと、移動教室そのものは影響がないという確認と、林間学園についての対応というところで、現段階の手だてを教えていただければと思います。"},{"i":25,"speaker":"篠田学務課長","text":"２年後のオリンピックの年の移動教室、それから林間学園の実施に当たっての考え方でございます。まず移動教室に関しましては、オリンピックの大会組織委員会から出されている日程が夏季の休業期間中の日程でございます。基本的に移動教室は夏季の休業期間は避けて実施してございますので、そちらの影響は基本的にはないものと考えてございます。\nそれから林間学園ですけれども、７月２０日の夏休みに入ってから３１日までの期間で実施してございます。それで、実際にその影響が出る期間、おおよそ３分の２ぐらいの期間が想定されております。要は、その期間中は、林間学園やクラブ、部活ですとか、そういったものはできるだけ日程・時期の変更等を考えてほしいというふうな要請をいただいております。そうしますと、学年で言いますと二千四、五百人の方が全体でおりまして、実際にこの時期に実施するのが、冬に林間学園のかわりにスキー教室を行っている学校もございますので、全部の学校ではありませんけれども、大体二千二、三百人のお子さんに影響が出るという中で、３分の２ぐらいの期間ですので、おおよそ１,５００人前後のお子さんに影響が出てくるだろうということで、現在検討を進めているところでございます。\n教育委員会としましても、実際に実施する各学校の校長会等々と、今、すり合わせをしながら、今後の対応を考えているところでございますけれども、一番大きいのは、林間学園につきましてもバスを使用するということで、こちらをどれだけ確保できるのかというのが一番重要な点でございます。正直、各バス会社も今、要請を受けていて、それから、どれだけ出せるかといったことを調整していると伺っておりまして、実際に林間学園のためにバスをどれだけ確保できるかというのは、まだ読めない状況でございます。ですので、現状としては、なかなか検討自体がどこまで深められるかということで、情報収集に努めているところではございますけれども、例えば残された３分の１だけの期間でできるかどうか。ただ、これも受け入れの日光のキャパシティの問題がございます。例えば、今、２泊３日で実施しているものを１泊２日にしたら、どのぐらい受け入れられるかですとか、あるいは、本来、林間学園につきましては教育課程外で行っているものでございますけれども、この年度に関しては教育課程内で授業期間中にできるのかですとか、さまざまな形での検討というのは、これから進めていこうと考えております。\nいずれにしても、情報がまだまだ足りない段階でございます。オリンピックにつきましても当然、品川区としては実施に向けて最大限協力をしていくという立場でございますし、この年のお子さん方だけが林間学園も満足な形でできないというのも非常にかわいそうな事態でございますので、できるだけ、どちらも両立できるような形でやっていきたいということで、今、検討しているところでございます。"},{"i":26,"speaker":"つる委員","text":"移動教室に関連してということと、また報道についてということの質問ですので、丁寧に答えていただいてありがとうございました。今、現段階でのというところもあると思いますが、これだけ大きい規模だと、予約といったものも、かなり早い段階で調整しなくてはいけないというのがあるのでしょうから、今ご答弁の中でもあったとおり、品川区も、競技開催都市というのがある中で、子どもたちにとって、オリンピックに触れる機会、それから林間学園という、いろんな日常とは違う学びの場というのでしょうか、それもしっかりと確保してやらなければならないというところで、なかなかその調整が大変だと思うのですけど、子どもたちにとって一番いい形となるように、早目早目の手だてを打っていただきたいと思います。よろしくお願いします。"},{"i":27,"speaker":"塚本委員長","text":"ほかにご発言はございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":28,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 学事制度見直しの検討状況等について"},{"i":29,"speaker":"塚本委員長","text":"次に、(2)学事制度見直しの検討状況等についてを議題とします。\n本件につきまして、理事者よりご説明願います。"},{"i":30,"speaker":"若生学校制度担当課長","text":"では、私から、学事制度見直しの検討状況等についてご報告いたします。\n今年の３月の学事制度審議会で答申をいただきまして、今年度、施策の方で具体化ということで、事務局で検討を進めてまいりました。今回、原案が一定程度まとまりましたので、経過とともにご報告させていただくものでございます。\nでは、１枚目の資料ですが、１「学事制度審議会答申後の経過」、（１）「答申の周知」でございますが、今年度、この答申の内容を、広報紙やパンフレット配布、町会・自治会長やＰＴＡ会長への説明等々で周知に努めてまいりました。並行して、答申を受け、具体的な制度の中身について、学区域、学校選択制について、教育委員会で就学人口等の調査を行いつつ制度の検討を進めまして、今回、原案という形で一定の整理をしたものでございます。\n続きまして、２「学事制度見直しの考え方について（教育委員会事務局原案）」ということで、こちらは基本的な見直しの方向性というところでございますが、審議会の答申の内容に沿って、基本的に整理したものになってございます。具体的な内容につきましては、後ほど別紙１から４で説明いたします。まずこちらの（１）「学区域の見直し」の考え方ですが、小学校から複数の中学校等へ現状分かれてしまっている学区域等がございまして、こういったことで進学先が分かれないように、中学校の学区域のほうを見直して、小学校の学区域を包み込むような形にするというようなことを基本とした見直しの方向性でございます。このことによって、小学校と中学校等がグループを構築することで、学校同士のつながりをより強固にして、義務教育の９年間の関係の一層の充実を目指しているものです。\n続きまして（２）「学校選択制の見直し」の考え方です。地域とのつながりや、あるいは通学等の安全といった観点から、小学校あるいは義務教育学校の前期課程の学校選択につきましては、現状、区内を４ブロックに分けて、ブロック内で広く選択できる仕組みですが、こちらは廃止しまして、隣り合う隣接の学区域の学校を選ぶ仕組みに見直す。こうしたことが方向性として書かれています。一方で、中学校と義務教育学校後期課程、いわゆる７年生の入学時の学校選択ですが、こちらは現行の区内全域自由選択というような形で、このまま継続することを基本として整理いたしました。\n続きまして（３）ですが、これらの制度の見直しに伴って、急激な変更への影響を緩和するといった観点から、一定の経過措置を設けるものでございます。\nそれでは、具体的な中身につきましては、別紙１のほうからご説明いたします。別紙１をお開きください。学区域の見直しに当たっての前提となる、小学校と中学校あるいは義務教育学校の組み合わせのグループ案になります。まず、前提となる考え方３点を整理させていただきました。まず（１）として、小学校の学区域は原則として動かさないことにし、その上でグループ設定は、小学校と中学校等の現行の連携関係を基本とするといったことを基本に置いております。続きまして、右側の（２）です。学校間の連携や、あるいは今後、コミュニティ・スクールを進めているところですが、そういったものを効果的に実施していく観点から、あまりに連携する学校が多いと、学校現場として支障が出てくる面も考えられますので、こちらにつきまして、連携する学校数は、中学校１校に対して３つの小学校まで、義務教育学校１校に対しては２つの小学校までといった形で上限を設けました。続いて、（３）、現行の連携関係に基づいて児童・生徒等の受け入れのシミュレーションを行った結果、学校として大幅に収容能力を超えてしまうようなことが予測されるところに関しましては、最終的にはお子さんが通えなくなってしまうと、かなり支障が出てしまうことになりますので、可能な範囲で組み合わせを見直すことにいたしました。\n以上の３点に基づいて整理したのが、下の表になってございます。基本的には（１）の条件において、現行の連携関係はそのままというのを１つの基本としていますが、一部、（２）と（３）といったところの観点で連携関係を見直した学校が、今年は小学校について３つございます。色をつけているところでございます。まず、（２）として、上限、学校数の関係で、連携が難しいだろうと判断したところで言いますと、左の表で真ん中ぐらいに、荏原第五中学校との組み合わせで４校、現行、小学校が連携していますけれども、ここでは、学校の距離や連携状況などといったところを総合的に判断しまして、一番下の延山小学校、荏原平塚学園との組み合わせを見直したものです。また、同じように（２）の観点では、日野学園、これは義務教育学校ですけれども、こちらが現状、御殿山小学校、第一日野小学校、第三日野小学校と、３校の小学校と連携しているということで、こちらについても減らす必要があるということ。それから、（３）の観点でも、やはり日野学園がかなり収容能力の観点で厳しくなってくるということから、御殿山小学校は品川学園との組み合わせが妥当であろうということで見直しております。この品川学園との組み合わせに関しては、現在も御殿山小学校というのは、品川学園の中学校部分、後期課程の学区域に入っているため、学区域上は何ら変わりがないという形になります。最後、もう一つの見直しとして、大崎中学校と連携している戸越小学校は、豊葉の杜学園の後期課程と連携するというような形で見直しをしているのですが、こちらにつきましては、現行、大崎中学校は３校と連携している中で、やはり将来的に大崎中学校の受け入れのキャパシティも相当厳しくなってくるという見込みがございます。また、隣接する戸越台中学校につきまして、組み合わせ等も考えられるところですが、やはり受け入れの状況も厳しいというところで、地域性等を総合的に勘案しまして、豊葉の杜学園としたところでございます。\n続いて、学区域の具体的な見直しの図が別紙２になります。データ上は２つの資料に分かれておりますが、紙の資料上は上下に分かれてございまして、上の学区域というのが現行の学区域。下が、先ほどのグループの設定案に基づきまして、基本的に中学校のほうを見直した形の学区域案になってございます。赤枠が小学校の学区域、色で塗っている部分につきましては中学校の学区域というふうに見ていただければと思います。下の図のほうでストライプの斜線で表示しているところが、中学校の学区域の変更の予定箇所でございます。ここで、小学校の学区域は原則として動かさないという方針で設定しておりますが、区の学事制度審議会でも、人口増等の場合には例外的に小学校の方も変えるというようなこともあり得るのではないかと答申をされているところでございまして、そういった観点で見ますと、現在、大規模開発、具体的に言うと武蔵小山駅前の再開発というところで、その一帯の小山三丁目に、今後４つの大型マンションが計画されております。こちら、学区域は、小学校は小山小学校になってございますが、今後、就学人口が非常に増えると見込まれることと、あと、小山小学校が改築が済んでおりまして、学校の受け入れ余裕も今後あまりないというところから、こちらにつきましては例外的に小学校のほうの学区域の見直しが必要であろうと判断したものです。具体的には、小山三丁目を、現在改築中の後地小学校の学区域のほうに、一部、見直させていただくということで、案を整理してございます。学区域の下の図で見ますと、左側のほうに、赤のチェックの線で表示している部分がございます。ちょうど小山台小学校の下の部分になりますが、こちらを後地小学校の学区域に入れさせていただくということで、案としては整理してございます。なお、後地小学校ですが、現状、８学級の比較的小ぢんまりとした規模の学校ではありますが、改築後はかなり余裕がある設計にしてございます。そういったことで、学区域変更後の増加分についても十分対応ができるような形で、今、設定しているところでございます。\n続きまして、次の別紙３のほうをお開きください。別紙３は、学校選択制の見直し案になってございます。小学校と義務教育学校の前期課程の選択について、見直す案でございます。現行の選択制ですが、左側の図のとおり、４つのブロックに色分けしていますが、こちら、広くブロック内を選べるような形から、右側の、隣接する学校、これは学校ごとに選択対象校を並べたものですけれども、学校ごとで隣接校がこういった形に変わるというようなことで見直しの案を設定してございます。ただ、隣接と言っておりますが、単純に接しているところだけにしてしまいますと、なかなか不都合が出てくる部分もございます。例えば区境、区の端のほうに接していて、ほかと比べると、選択できる学校が非常に少なくなってしまうようなところ。極端に少なくなるというところに関しては、やはり一定程度、距離が近い学校を１校追加して、最低でも３校は希望できるようにということで整理したものです。具体的に言うと、８番の第三日野小学校が該当するものです。\nもう一つの特例としまして、これは答申でも出されましたとおり、単体の小学校と義務教育学校は、少なくともどちらでも選べるような形をとるべきだろうということで、ただ、隣接にしてしまうと、義務教育学校が隣り合わないというところがかなり出てくるものですので、こういったところについては黄色で表示していますが、１校、義務教育学校を、直線距離で最も近いところという観点で追加したものでございます。さらに、これはちょっと特例というか、経過措置の分野に入るのですけれども、括弧書きで２１番と３１番、それぞれ小山小学校と小山台小学校を、赤字で括弧で入れています。こちらは、先ほどご説明した、小山小学校の学区域の一部の見直しに伴って、隣り合わなくなってしまうといったことが生じることから、これは一定期間、隣接校に準じるような形で配慮すべきであろうということで、それぞれを一定期間は選べるような形で入れているものです。学校選択制は以上になります。\n最後、別紙４になります。経過措置の考え方になります。こちら、基本的な考え方として３点整理しました。まず１点目としまして、それぞれ学区域・学校選択制変更後も、旧制度で入った兄弟姉妹関係、お兄さんやお姉さんといった方が在籍する限りは同じ学校に通えることを最優先とするということです。２点目、そういった兄弟関係がない場合の、学区域が変わってしまった対象者につきましては、やはり一定期間は、旧学区域の学校を希望選択できることとしまして、この順位としましては、兄弟姉妹優先の次の順位というような整理をしています。ただし、現在通われている在校生の方については、学区域変更後もそのまま卒業まで通うといったものを原則として考えてございます。３点目として、こちらは学校選択制のほうですが、小学校の学校選択が変わるとなった場合に、一定期間は、旧制度で選択範囲の学校、ブロックの中で選びたいというような方に関しても、一定の配慮が必要だろうというところで、こちらは一定期間、選べるようにしますけれども、優先順位としては、新しい制度で隣接校になったことで、そこを選択された方の次の順位というような形で考えてございます。\nこの考えをもとに、パターンとして整理したのが、下の表になってございます。若干わかりにくいかと思われますけれども、兄弟姉妹関係以外の2)と4)の経過措置期限につきましては２年間とさせていただいております。学区域・学校選択制の見直しに関しては、区民の皆様も非常に影響が大きいということで、こちらについては、本区の過去の学区域の変更事例やほかの自治体の変更事例等も踏まえまして、当初、周知期間を１年とりまして、なおかつ経過措置を２年ということで、制度の公表から完全に移行するまで３年間が妥当ではないかというような形で考えたものです。以上が見直しの原案になります。\n１枚目に戻っていただきまして、３「新制度の構築に向けたスケジュール（予定）」でございます。今年度、教育委員会で取りまとめた原案は、来月以降、地域等に対して説明してまいります。その中で丁寧にお話をお伺いしながら制度をまとめていきまして、今年度中に新制度として決定したいと考えてございます。来年度ですが、平成３１年度は周知期間と捉えまして、さまざまな手段で丁寧かつ確実に周知していく予定でございます。その上で、再来年度、平成３２年度の新入学の１年生・７年生の方から、新しい制度で実施していくといったスケジュール感で進めてまいりたいと考えてございます。"},{"i":31,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":32,"speaker":"南委員","text":"何か本当に大変だったのだと思いますし、説明を何回聞いてもよくわからない。相当、頭のいい方が作られたのだろうという感想です。\nそれで、来年度は周知期間で再来年度から実施ということなのですけれども、私どもはこういう学校選択制については反対という立場で臨んできたのですけれど、そういう中で実施しているというところで、あえて質問したいと思っています。来年１年間の取り組みが、どれだけ周知徹底できるか、混乱を来さないようにするかということが重要だと思うのです。それで、この表にあるところの限りでは、いろんな媒体を使って周知をするということなのですが、一番肝心なのは、平成３２年度に１年生になる方、７年生になる方の保護者あるいは子どもにきちんと変更した状況を理解していただいた上でということで、選択制にせずに、自分の学区域のところに行きたいという方は別としても、学区域が変わるわけですから、そういう点できちんと理解していただくという作業が大変重要なのだろうと思うのです。学校の中だけではだめなのです。入ってくる方ですから。その辺は具体的に現実的にどういうふうな体制をとろうとしているのか、まずそこをお尋ねしたいと思います。"},{"i":33,"speaker":"若生学校制度担当課長","text":"来年度の制度の周知に関してですけれども、もちろんご指摘のとおり、これから入られる１年生、それから７年生の選択される方々、要は１年生で言いますと就学前の保護者といったところへの周知が非常に重要になってくると、私どもも考えてございます。周知の具体的な方法としましては、やはりこちらに書いてあるとおり、広報紙・ホームページ等以外にも、周知用パンフレット。こちらは、かなりわかりやすいものを作成する予定で考えてございまして、こちらをまず、就学前の通われている保育園や幼稚園、児童センター、あるいは健診の場や、いろいろな区の施設を利用される、小さい子が行かれるようなところに幅広く置かせていただいて、なおかつ、個々に、保育園でしたらもう全員に行き渡るような形で必ず配付させていただくということで、それから保育園・幼稚園の職員の皆様にきちんとご理解いただけるように周知をしていく予定でございます。"},{"i":34,"speaker":"南委員","text":"同時に、直接的に説明する立場にないとは思いますけれども、非常にかかわるところとしてＰＴＡがあると思うのです。ＰＴＡの方々にも、この答申について、この間、会長に説明をしたとはなっているのですけれども、もちろんいろんなご相談がされることもあると思うので、当然、ＰＴＡも対象にしているのではないかと思っているのですが、ここのところはどういうふうに捉えているのかを伺いたいのと、やはり当然、来年のちょうど今ごろの時期に、教育委員会に問い合わせが殺到すると思うのです。そういうときに、電話での相談だけではなく相談ブースのようなものを設けるなども含め、きちんと不安を払拭して入学していただくということが一番大事ですので、そういうこともどういうふうに捉えているか、その辺も伺いたいと思います。"},{"i":35,"speaker":"若生学校制度担当課長","text":"まずＰＴＡへの周知でございますけれども、教育委員会としましては、答申につきましても会長の集まる全体会で周知させていただきましたので、そういった場を活用してきめ細かに周知していきます。それと、個々の学校のＰＴＡの皆様に関しましても、やはりそこは学校を通じてになるかと思うのですが、校長や学校の現場の職員の方々からＰＴＡの役員の皆様等にもきちんと周知させていくような対応をとっていく予定でございます。また、区への問い合わせへの対応等についてですが、ブース等も設けてというご提案がありましたが、そういったことも含めまして、きちんとこれは対応できるような対処をとってまいりたいと考えています。"},{"i":36,"speaker":"南委員","text":"かなりの労力を費やして学事制度審議会を１年間やり、そしてその答申をいただいて、１年間の時間を要しながら実施に移していくということなのですけれども、学校選択制はかなりのところで、２３区の中でも廃止している状況がある中で、こういうふうにしていくという、かなりの労力を費やさざるを得ないということについての、やはり矛盾というか問題というか、そういうところを感じないではいられないと私は思っています。区の皆さんの努力は、それはそれとしてご苦労さまでしたとは思うのですけれども、やはりそれだけの労力をかけながら維持しなくてはいけないものなのかというのを非常に感じました。これは意見として申し上げておきたいと思います。"},{"i":37,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":38,"speaker":"飯沼委員","text":"私もこれは２日かけて見たのですが、本当に、個別の事例で比較して見ていかないと、なかなかわからないです。本当にこれはご苦労されたと思いますし、経過措置を含めると、さらに複雑。事務も大変だけれども、実際に我が子のことを考えて選択していく苦労が、兄弟姉妹関係も含めて、今まで以上に複雑になっていると。はっきり言って、すごいと、ため息が出ました。具体的に、通学の距離の問題なのですが、小学校のときは、なるべく近く、あまり遠くならない、近隣校というところで、少しは改善されているのかなと思うのですが、でも結構まだ広いなというのと、あと地域とのつながりをとても大事にされている、地域の方々にとって、その辺というのは改善されているのかというのが１つです。\nあと、やはり地元の方の意見をしっかり聞いて、これから町会に聞いてというのももちろんですけれども、地元の声を聞いていくという、そこのところの重要性をしっかり捉えていただきたいと思うのですけれども、具体的にどんな説明をして意見を聞かれているのでしょうか。私などは、要求があったところにきちんと説明に行く、出向いていくとか、そのぐらいしていい中身であると思っているのですが、内容の説明と意見を聞くという調整をどうされていくのかを教えてください。"},{"i":39,"speaker":"若生学校制度担当課長","text":"２点いただきました。まず、地域とのつながりのところでございますけれども、今回の学事制度審議会の議論から、こちらでの見直しの案というところでの検討に一貫して、やはり地域とのつながり。これは、地域とともにある学校づくりをより進めていくといった観点での見直し。選択制につきましても、近隣を選べるような形。それから学区域につきましては、基本は小学校の学区域は変えないと。一部ちょっと変更が必要な部分は出てくるのですが、そういったことをベースに、非常に、地元、地域を重要視した方向性になってございます。そういったところで、地域への説明というところでも一定程度、ご理解を得ていきたいと考えているところです。\nそれから、２点目の、地元の意見等、ご説明の仕方につきましては、今後、来月以降、町会・自治会等、ＰＴＡも含めまして、これは、例えば町会・自治会関係につきましては、もう連合町会は満遍なく変わるものですので、ここはやって、ここはやらないというわけにはいきませんので、ここはきちんと全て回りまして、ご説明、ご意見を伺ってまいりたいと考えております。"},{"i":40,"speaker":"飯沼委員","text":"連合町会というところなのですけれども、私は武蔵小山の地域が近いので、ぱっと見て、ああ、小学校の学区がかなり変わるなと思って、これを理解するのに時間がかかったのです。入れかえがあったりして複雑で。そういった意味においては、本当に地元の方々に中身をしっかりわかっていただくというのは大事なので、連合町会といわず、もう少し細かくお願いしたいです。あと、やはりわからない、いろいろ質問が出たから来てほしいと言われたら、ぜひ出向いていって説明もしていただきたいと思います。武蔵小山の開発のところが影響しているのかと、改めてそうだなと思いました。４棟だけで２,０００世帯ぐらい増えるのです。それで、４棟で済まない話が今、起こっているのです。だから結局、そういうところが、例えば後地小学校の建て替えにつながっているんだというのを改めて認識したわけですけれども、本当にまちが変わると、保育園もそうですが、学校もすごく影響を受けるということで、このごろ本当に若い世代が移ってきて、結構、教育の問題、保育もそうですけれども、関心が高いです。やはり将来、きちんと見通せるような説明が事前に本当にされていなくてはいけないと思うので、そこをよろしくお願いしたいと思います。\nあと、やはり南委員もさきほど学校選択制については意見を述べましたけれども、答申の１０ページに運用状況と書いてあったり、やはり希望申請者が下降して減っている。二十五、六％の人に減っているのです。そういった意味で、やはり安心して地域に通えるというところにおいては、本当に、私たちはずっと、学校選択制はやめてほしいと思っています。もっとシンプルな状況の中で安心して地域に暮らせるというところがやはり大事で、検討した結果、評価的にはさらに難しくなっているのではないでしょうか。あと、一番心配するのは、学区域の児童だけで定員が埋まってしまって、選択の枠の確保ができない学校が増えているということ自体において、ここがまたどう展開していくのかと。これは意見ですが、やはり、小さいうちから公立の学園で抽選が行われるなどということは、私はあってはならないと思っています。今からでも遅くないので、見直せるのだったらぜひ見直していただきたいという意見を述べて終わります。"},{"i":41,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":42,"speaker":"石田（し）委員","text":"まず周知についてですが、先ほどのご答弁の中でも、保育園等にもしっかりと周知していくということだったので、そこはまずぜひお願いしたいというところですし、これはやはり、見てもなかなかわかりづらいです。何も知識がない人が、これを見て、「ああ、そうなんだ」とすぐ理解するのはなかなか難しいと思うのです。そんな中で、例えば、これはもうできる限りわかりやすいように、説明や周知をしていただきたいのですけども、例えば親御さんも見るのは限られたエリアだと思うのです。品川区全域を見るわけではないので。なので、例えば別紙３にあるような、例えば品川・大崎ブロックとか、見るのは各ブロックぐらいなのかと。ですので、そのブロックでのわかりやすい周知の仕方というのをしていただけるといいと思います。全体が全部出てしまうと、もうその時点で、「これは何だ」となってしまうと思うのです。なので、保護者の方たちに理解してもらうためには、ブロック単位等、もう少し具体的な部分で周知していただけると、少しはわかりやすいかと思うので、その辺の工夫はぜひしていただきたいと思います。いわゆるピンポイントで。それで、これは、基本、いわゆる子育て世代に対してのアピールといいますか周知だと思うのです。ですので、そこの部分も、先ほど広報紙だとかホームページとか説明がありましたが、そこはもちろんしていただきたいですけれども、さらに踏み込んだ、直接的にその世代に届くような手法で周知していただかないと、なかなか届いていかないと思うのです。例えば保育園や幼稚園の子どもたちにということですが、これは周知をぜひしていただきたいと思いますし、いろんな方法を用いて、これは伝えていただきたいと思います。\nそれと、これは確かに、これからの子どもたち・保護者に周知をするのはもちろんなのですけれども、実は、例えば兄弟姉妹の話などが出てくる場合には、既に学校に通われている方たちの保護者にも、やはり何らかのアプローチをしていかないと、知らなかったということになってしまいます。それで、逆に今までの制度を知っている人たちが、この制度を知らずに、入学の前に気づいてしまうと、もっとややこしくなるといいますか、大変なことになってしまうのかと思うので、在校されている保護者の方たちにも、「この学校選択制の方法は終わっています」と言うのではなくて、しっかりその辺は周知していただきたいと思います。例えば、いわゆる世代でのコミュニティの情報の中で、間違った情報が行ってしまう可能性もある。例えば今の制度を知っている保護者たちが新しく入る人たちに聞かれた場合。やはり先輩に聞きますよね。「うちも学校を悩んでいるのだけどどうしようかな」と。前の制度のまま話されてしまったら大変なので、その辺も含めた周知方法で、ぜひ行っていただきたいと思います。これは要望で終わります。\nそれと、いわゆる兄弟姉妹に関しては第一優先でやっていただけるということなのですが、以前この委員会でもお話をさせていただきましたが、非常につらい思いをされている方たちも中にはいるというお声を聞いていますので、この辺はしっかりやっていただきたいと思います。\nそれと、もう一点、私もつい最近知ったのですけれども、学校選択というのは、年度途中だと対象にならないのです。一番最初の入学のときや新年度のときのみで、途中で例えば引っ越しをされた方たちが、学校を選択しようと思ってもできない制度になっているようなので、この辺は何とかならないのかと、ちょっと感じているところであります。ですので、年度途中での対応というのはどのようにされるのかお答えいただきたいと思います。\nそれと、コミュニティ・スクールも品川区では進めていますが、コミュニティの中に学校も入っていくといった中で、実は見直し後の学区で、やはり若干、もちろんいろいろな事情があっての変更だったりするのは重々わかっているのですけれども、私が活動しているエリアに大崎第一地区があって、第四日野小学校というのが荏原の地域のほうに少し寄りがちというか、加わっていくといった中で、荏原地区と大崎地区という２つの地区にまたがって子どもたちが活動する中で、地域では大崎第一地区でのさまざまな地域でのイベント等があって、荏原では荏原でいろいろなものがある中で、ここが一番、いわゆる町会長たちの、学校選択制の一番疑問に思っているところというか、なかなか納得できない部分なのかと思うのですけれども、やはり地区は地区でさまざまな活動がある中で、その地区をまたいでの学校になってしまうと参加もしづらくなるのではないかといった懸念もあります。いわゆるコミュニティ・スクールというもの、また地域というもの、学校というもの、この辺をどうやって今後、見直しをした後にクリアにしていくか、活動しやすいようにしていくか、何かお考えがあればお聞かせください。\nそれと、もう一点なのですが、今、保育園に預けられている親御さんたちも多い中で、保育園も実は一番家から近いところを第１希望にしていたとしても、そこに入れず、それこそ第３希望、第４希望になってくると、家から離れているわけです。そうなると、離れた保育園に、でも入れたから、そこにずっと通わせた。友達もいっぱいできた。でも学校にいざ入るとなったときに、学区が違うと。せっかく仲よくなった友達とは、もうそこでさよならをしなければいけないといった事案も、ここ最近出てきているのです。そういった中で、住んでいるところというのはわかるのですけれども、そういった新しい課題、今までなかったものも出てくるわけです。今後、もちろん保育園・幼稚園のいわゆる選択という部分になってくるのかもしれないですけれども、その辺もどのように考えているのかというのを、ぜひお聞かせいただきたいということを思います。以上、質問は３点です。わかる範囲でいいので、よろしくお願いします。"},{"i":43,"speaker":"篠田学務課長","text":"私からは、いわゆる学年の途中の学校選択の考え方についてご説明させていただきます。もともと学校選択制が導入されたのが、新たに学校に入るときに選べる制度ということで、そのことによりまして、保護者の方、お子様方の選択というのもありますし、あわせて学校を活性化していくと。その当時の学校のあり方についてもさまざま議論があったところでございますので、そういった部分で導入させていただいたところでございます。それで、学年の途中ということですが、従来からそういったご要望は確かにいただいているところではあるのですけれども、学校の選択は入学の当初に行われまして、そのことによって、例えば学校定員の問題ですとか、実際に抽選が行われたりした場合の公平性の問題ですとか、さまざま課題があるものですから、現状では学年の途中で編入された方については、学校選択という形ではなく、特別の事情があれば、いわゆる指定校変更でお受けして、検討していくという形で対応しているところでございます。今回の見直しに当たりましても、その部分に関しましては、特別、変更する予定は今のところはないものでございます。"},{"i":44,"speaker":"若生学校制度担当課長","text":"荏原地区と大崎地区との関係で、ちょっと分かれてしまっているところに関しての考え方ですが、第四日野小学校に関しましては、上の図を見ていただくと、現行も荏原第一中学校との連携が行われておりまして、お子様の進学につきましても、やはり日野学園に一定程度行かれる部分はあるのですが、連携は荏原第一中学校とのつながりが強いというところで、こちらも考慮した上で、ただやはり地域とのつながりという面で見ますと、町会等は荏原ではなく大崎のほうに入るというようなことで、その辺に関しては今後、地域とお話しさせていただく中で、どういった対応が可能かというところも考えてまいりたいと思います。一方で、第四日野小学校自体、小学校の学区域自体は変わりませんので、そういった部分での地域コミュニティというのは、一定程度、確保できるものと考えております。\nそれから、３点目の保育園からの人間関係の問題です。そういったところで、現在の小学校のほうに、友人関係で上がられるという声は、いろいろ聞いているものではございます。保育園に関しましては学区というものがないものですから、どうしても小学校と一致しないというようなことは出てきてしまいます。ここは、制度上、やむを得ない部分ではあります。ただ、今後、そういったところが出てくる部分がございますので、保育園からの動向というのも、こちらとしては把握した上で、どういった手だてがあるのかというところも考えてまいりたいと思います。"},{"i":45,"speaker":"石田（し）委員","text":"保育園、幼稚園の件は、ぜひ情報共有を含めてやっていただければ、やはり情報があれば何らかの対応も可能になってくるのかなと思いますので、そこはぜひ情報共有をしていただきたいと思います。\nコミュニティ関係の件については、ぜひ各地域の方たちとアイデアを出し合いながらやっていただきたいと思います。\n年度途中ですが、最初のご答弁を聞いて、そうなのです。そうなのですけれども、現実はそうではなくて、途中で学校を変えたいという人は、その理論でいいかもしれないけれど、引っ越しをされたお子さんというのは、月が違うだけで、初めてそこに入学するのですから、入学の選択権というのはここに与えられるべきであって、それを、年度途中だからといってだめだというのはどうなのでしょうか。確かに、一番初めに抽選されていて、抽選漏れなどがある学校に関しては、それは、その子どもたちの公平性の問題などもあるので、一定の理解はできるのですけれども、例えば、空きがある中で選択させないというのはどうなのでしょうか。いろいろな事情がある中で子どもは引っ越したくて引っ越したわけではないでしょうし、子どもは子どもで引っ越してきたところで、やりたいことというのもあるのかもしれない、そこの学校に行きたいという何らかの理由があって。それで、先ほど指定校変更で対応しているとおっしゃいましたけれども、私が聞いている限り、指定校変更というのは、よほどの事情がない限り認めないと言っている中で、対応しているとは到底思えません。なので、ここはやはり、今こういった見直しがある中で、その部分もしっかりと見直しをぜひ取り組んでいただきたいと思います。私はいつも、一番は、子どもたちが楽しく学校生活を送るために、できるのであれば、そういった制度を活用して、子どもたちにはそういった学生生活を送ってもらいたいという観点で申しあげているわけであって、別にこの制度を否定しているわけでもないです。ただ、そういった課題がそこにはあるのだというのを、ぜひ認識していただいて、変えられるのであれば、もちろん一定の条件はつけたとしても、その辺の柔軟な対応をぜひとっていただきたいと思いますけれども、そこを改めてご答弁いただきたいと思います。"},{"i":46,"speaker":"篠田学務課長","text":"委員からご指摘がございました、年度途中での編入における学校選択の話でございます。今のお話の中にもございましたとおり、空きがあればということで、公平性の観点からいくと、例えば抽選の行われた学校の学年に途中から入れてしまうというのは、やはり公平性が保てないというのがあって、現状では学校選択を年度途中の編入では認めていない、制度としてもないということでございます。\n指定校変更で今、対応しているということで、実際になかなか条件が厳しいというのは、確かにご指摘のとおりでございます。さまざま課題等あることは私どもも認識しておりますし、今後どういった形で対応できるのかというのは研究していく必要はあるのかなとは考えているところでございます。"},{"i":47,"speaker":"渡部委員","text":"ここまで本当に、３月にまとめられて、半年かけて事務局で練っていただいて、最終的にといいましょうか、今お示しされている検討状況ということで、ここまで詰めてこられて、本当にありがとうございました。私たちも学事制度審議会というのは、ともかく煙も立っていないときから、やれ、やれといって、平成２０年のときの答申から、では何か変わったのかといいながら、これも早急にやるべきだということで、それがこのような形になってきたということで、会派としても勉強をずっと続けさせていただいていて、本当にありがとうございます。\nただ、これからが大変なのだろうという中で質問させていただくのですが、今ちょうど石田しんご委員からあった話は、仕組みとしてはわかっていて、もうそのとおりだと思うのです。ただ、今、これは新たな大きな制度変更を、品川区の長期基本計画が始まる、そして、日本の国の中で教育要領が変わっていくという、このタイミングで、平成３２年というすばらしいタイミングでできるのですから、そこも研究材料で間に合うのであれば、年度途中、学校選択にしていいのではないかと思います。というのは、入らないところは当然、注意書きが必要で、年度当初に抽選になったところは選べませんけれども、例えば引っ越した先で隣接している学校は入れますという、丁寧な注意書きを一言添えれば、就学相談、住民票の異動、転居届など出されたとき、就学相談があるのでしょうけれど、そういうときに簡単なチラシ１枚で済むのかなと思います。その中で学校をお選びくださいでもいいのかなと。いや、そのほかに何かいろいろな仕組みがあって、それでは難しいと言われれば、それまでなのですけれども、せっかく品川区に住まれる方は、多分、今の石田しんご委員の話ではないのですけど、学校選択制があるとか、お子さんがいらっしゃれば、そういうことも十分承知して、小中一貫の教育がなされているなどというふうに来られていると思うので、これはできるかできないかわからないのですけれども、検討してほしいと思う。そこだけ「検討します」と言ってほしいのですが。"},{"i":48,"speaker":"篠田学務課長","text":"さまざまな形でご要望いただき、特に引っ越しされてこられる方々からも、そういったお話は従前からいただいているところでございます。確かに非常に重要な課題であるということは認識してございます。それで、今回の見直しに当たってすぐにこれを打開できるかどうかはなかなか難しい部分もあるかと思うのですけれども、今後、こういった部分がどういった形で対応できるのかどうかということも含めて研究していく必要はあるかと思います。"},{"i":49,"speaker":"渡部委員","text":"わかりました。よろしくお願いします。\nこれから地域のほうに説明に歩くという中で、今回、中学校の学区域を変更するということで、さまざまなご意見が出てくるのは、もう皆さん承知されていることだと思うのです。これは中学校の選択制が、前回の答申が出て４月の説明のときだと、ある程度、小学校がひもづけになることで、また選び方が変わるのかなとか、中学校が選べなくなるのかなと思っていたのですが、今回の見直しで中学校は基本的に選択制が変わらないですよね。学区域のほうで、通学区域で縛られたとしても、選択制が変わらないのだから従来どおりなのですよということは、逆に地域の方にいろいろ言いやすくなったのではないかと私は思っているので、前から申しあげているように、コミュニティの単位というのは、私は中学校ではなくて小学校だと思っているのです。これは会派全体がそういうふうに考えています。それで、品川区の教育上、中学校があって小学校があるというのは、これもご理解いただくところなのですけれども、あくまでも地域町会にお話しされるときは、小学校が単位なのだと言っていかないと、「ただ品川区の教育のために学区域を変えられた」などとなってしまいますから、その積み上げというのが、中学校があって、そこはやはり一本でやっていくのが品川区だというような、説明の仕方の違いだけだと思うのですけれども、それで理解はされやすいのかなというのが１点あるので、これは意見として申しあげておきます。\nそれと、説明に歩かれるのに、町会、連合町会、町会長たちにという話なのですけれども、そこから下には話がおりないのです。私も町会の総務部長をやっているのですけれども、大抵おりません。町会役員にもおりないということは、その下に当然おりるわけがない。おりるわけがないと決めつけてはいけないのですけれども、なかなかおりづらい話でありまして、先ほど、学校経由でＰＴＡということで、これも大事ですけれども、ＰＴＡ会長からＰＴＡの役員に確実におりるかというと、これも私の経験上、なかなか細かい話もおりない。というのは、間に１人、２人いると、話が全然違う伝わり方をしていきますので、ここは難しいのかと思います。これは私はお願いとして、説明に歩かれるのであれば、まず、品川区は同窓会組織が結構しっかりされている中学校が多いですよね。そこは丁寧に、まずご説明いただきたいと思います。小学校にも当然、同窓会組織があれば、そこにも何らかの説明をこれは学校経由で結構だと思いますが、何かのときに行ってください。\nそれと、先ほど来、当然、７年生の入学というのは品川区の教育を受けていて、ある程度、子どもたちがどこの学校に行きたいというのもありますし、中学校はさほど大きな変更がないのでいいのですけれども、では新１年生を迎えるというときに、まっさらの新１年生の方のほうが私は安全だと思っていて、逆に兄弟姉妹関係がある１年生のほうが、これは混乱を来すわけです。やはり保護者会で丁寧な説明が必要なのかと思います。しかも早い段階で。大勢いるところで説明をされたいのと、同様に、例えば区立保育園ですとか、児童センターですとか私立の幼稚園ですとか、ポスターなりカタログなりできた段階で、掲示を始められたいです。それで、問い合わせに関しても、ブースだ何だというのですが、なるべく問い合わせが出ないような仕組みでお伝えできるようにしてほしいと思います。例えば、私たちはこういう仕事をやっていて、こういう議論をしているので、隣接校と言われたら、地元の学校であれば、すぐわかるのですけども、普通の住んでいる人は、隣接校がどこかわからないですから。もう何十年も品川区に住んでいる人は別ですけれども、一目瞭然でわかるような仕組みづくりはしてほしいと思います。\nそれで、スケジュール感。これは１枚目のところで質問していきますけれど、平成３２年４月からスタートするということは、もうこの間、案内を見せてもらいましたけれども、１０月で学校選択制を締め切るので案内をつくってお配りする、あの冊子は夏ごろにはできているのですよね。逆に、それまでに全部終わらせなければいけないわけですよね。今から１年ないのです。それで、今、ゼロベース。これから話を始めていこうという中で、ここである程度、あらあらなのはわかっているのですけれど、せっかく委員会なので、どういうスケジュール感をもって、どこが最後というか、フィックスさせて、この仕組みでいくのだというのは、私は、実はもう、夏休み前にはそこまで持っていっていないと、準備が実は平成３２年に間に合わないのではないかなどと不安を抱いてしまったのですけれども、その辺をちょっと詳しく説明してください。スケジュール感のところを。"},{"i":50,"speaker":"若生学校制度担当課長","text":"スケジュールに関してのご質問ですが、まず周知に関しましては、当然、平成３２年度から実施していくには、その前の年度、平成３１年度の秋、１０月からの学校選択制の手続に間に合わせるように、１カ月先取していくということが必要になりますので、そのパンフレット等が配布されるのが９月ということで、パンフレットには、きちんとした、新制度の周知というのは当然盛り込んでいくものでございまして、ただ、９月まで、配布されるまでの間に、きちんと、やはり浸透していないと、選択行動に入れないというところもございますので、もう本当に４月に入ってからすぐにパンフレット等も浸透させて、いろんなところに置かせていただいたり、直接配付させていただいたりしながら、確実に周知してまいりたいと考えています。"},{"i":51,"speaker":"渡部委員","text":"多分、みんな同じだと思うのですけれど、みんな気づいているといいますか、同じことを考えていると思うのですけど、今回、大きな変革を起こそうとしていて、しかもそれをしっかり周知して、こういうものなのだというのは、伝えるだけでは多分伝わらないですよね。それをわかってもらうというのも、当然、保護者みずからが理解しようと動いてもらわないと、なかなか動けないと思いますので、ありとあらゆる手段をぜひ考えていってほしいと思います。それで、それに関しては、もう教育委員会だけではなくて、区長部局なども巻き込んで、当然、子ども未来部も巻き込んでやっていかなければ、品川区の大きな教育制度の変更になりますし、逆に平成３２年から小中一貫教育というのが、しっかりまた連携をとられて進められていくというのも、すごくチャンスといいましょうか、そういうところだと思います。学校選択制に関しても、多分、ブロック制のときよりも、隣接校、品川区は学校がくっついていますから、そんなに歩いてかからないし、結構喜ばれる制度で間違いないのです。選択行動がどうなる、こうなるというよりも、仕組みがあるということが、十何年続けてきて、それの、ある程度集大成で、これから１０年も２０年も多分この仕組みでいけるような仕組みなのだと思いますので、しっかり丁寧に周知を進めていただいて、平成３２年には新しい形で進めていただきたいと思います。\n委員長、お願いですけれども、これから都度、さまざまな配布物等ができることがあれば、私たち文教委員のメンバーにお配りいただくよう、お伝えください。\nというのは、多分、私たちに相当問い合わせが来ます。ここにいる人たちも普通の議員もみんな、町場のことが来ますので、よろしくお願いいたします。"},{"i":52,"speaker":"塚本委員長","text":"はい。\nほかにご発言はございますか。"},{"i":53,"speaker":"つる委員","text":"まず、この経過措置は、多分、十分にいろいろ対応いただいているということで、他区ですけれども、「突然、選択制が中止になってしまって、本当に大変で」と、該当区ではないのですけれども、私のところに「どうしたらいいのでしょうか、何とかならないのですか」とその方が相談に来たというようなことがありました。逆に言うと、品川区がこういう形で経過措置をしっかり十分とっているということを見れば、周知はそれぞれしっかりとやっていただいた上で、そのセーフティではないですけれども、こういう形であるというのも、すごく大事なことだと思います。すぐ隣の区でそういうことがあり、「それはちょっと丁寧ではないな」という感があったものですから、そこは非常に丁寧だと思いますので、しっかり今後、そういったことも含めて、経過措置がちゃんとある等というのも含めてやっていただきたいと思っています。\nその上で、先ほど飯沼委員からもありましたけれども、今回、小学校区域のことでは、まさに武蔵小山の駅前、小山三丁目ですが、目の前の武蔵小山パルム駅前地区のところ。まさに目の前のところが、２０２０年の４月入居です。それで、すごくコアな話になるのだと思うのですが、６２８戸のうち４９１戸が販売戸数で、当然、区内の方もいらっしゃるのでしょうけれども、区外の方も相当数いらっしゃる。なおかつ、ご購入されている世帯が、どちらかというと未就学児童のいる世帯が多いということも報道されている中で、タイミング的に、では４９１戸ないし６２８戸のうち、どれだけ２０２０年のときに１年生として入ってくる方が世帯としているかなどという数字もあると思うのですが、先ほどの石田しんご委員の話ではないのですが、当然、年度途中、学年途中の方もいらっしゃると思うのです。そういう方への、通常、引っ越しとか転勤とか転校とか、いろいろある中で、すごく多発地帯、これは毎年あるのかわかりませんけれど、ただ、ここに限っては、それだけの大きい方がどんと来て、なおかつ小学校の学区域も変更されるわけですよね。今さっき言った経過措置もあるのですけれども。そうすると、今、現段階で、例えば販売会社ですとか売主ですとか、どういう形でも、入ってこられる方に早くそうした情報が入っていくという手だても、ここに関しては、すごくコアな部分なのですが、必要なのかなと思います。もしかするとそれだけ対象世帯が大きい可能性があるので、すごく部分限定なのですが、このあたりをどういうふうに考えていらっしゃるか教えてください。"},{"i":54,"speaker":"若生学校制度担当課長","text":"武蔵小山駅前の開発に伴って、学区域の小学校のほうの変更の対象となる、特にマンションを購入される予定の世帯の方、ご家族がいらっしゃってというところに関して、きちんとやはり周知する必要があると考えてございます。現状、どのぐらいの世帯数か、どのぐらいの方がという情報はつかんでいないところではございますけれども、今後、こちらで制度がきちんと固まって周知していく段階で、いち早く、そういった武蔵小山駅前の小山三丁目については小学校のほうを変えるということで、より影響が地域等にも大きい部分でございますので、そういったところで、ディベロッパーですとか、そういったところとの連絡というのがもし可能であれば、そういったところを通じて、直接、対象となる方についても周知できるような形を考えてまいりたいと思います。"},{"i":55,"speaker":"つる委員","text":"先ほど渡部委員から言っていただきましたとおり、飯沼委員も先ほど言っていましたけれど、本当におそらく問い合わせ、私もエリア的に相当数あるのだろうと想像すると、やはりそうした資料なども早目に頂戴できると、それはそれでありがたいです。当然、ほかの方と同じようなタイミングで、入られる予定の方たちに情報が入るということも、引っ越してきたときに、いろんな混乱というか、そういう対応で困ってしまうというようなことがないことがすごく大事ですし、あくまでも予定なのですけれど、４月上旬入居というので、もう年度は始まって、「ああ、そういうタイミングなのだな」と。それはあくまでも、マンションの都合だとは思うのですけど、ただ、そういう情報というのは、通常、引っ越しも既に予定しているから、親御さんのほうで、引っ越し先の自治体、私たちであれば品川区の教育委員会への問い合わせとか、当然するのだと思うのです。そのときから、こういうふうになるのですよというようなことが、同じようなタイミングで行き渡るということも、これから区民になっていただく方という意味ではすごく大事な配慮なのかなというところがあると思うのです。\nただ、余計なことかもしれないのですけれども、結構、マンションの販売価格帯、相当高いですよね。そうすると、それだけではないですけれども、品川区の公立に、入られるか、私立に行かれるか、それはわかりませんけれど、そういう世帯の志向性というのは私はわからないですけれど、ただ、やはりそういう選択の意味でも、しっかりとそういう情報がきちんと、今ご答弁いただいたような形で行き渡るようにぜひやっていただきたい。本当に、まさにたまたま、これは２０２０年、平成３２年４月というところに、ちょうどぴったり来てしまっているので、そこだけはお願いしたいと思います。"},{"i":56,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":57,"speaker":"高橋（し）委員","text":"さまざま、今、質問と答弁があったので、いろいろ理解させていただいたのですが、ちょっと確認で、１つは、今、原案という形で出てきているのですが、スケジュールの中で、「説明・調整」とあり、そして「新制度の決定」とあるのですけれども、決定というのは一体、どこでどうなると決定であり、それが、パンフレットは４月からといいますけれども、「決定した」というのは、もう一度、委員会等に伝わるのでしょうか。その決定の内容というのは、私もちょっとわからないので確認するのですが、学校選択制についての細々としたところは要綱には出ていないようですけれども、何を変えることによって、これが要するに新しい制度になるのかというところが、すみません、法規上どうなるか教えてください。\nそれからもう一つ、先ほどほかの委員からもありましたが、学区が変わる、あるいは選択が変わるので、幾つか動きがあるということで、説明のときに小学校では前回どおりの抽選の数になるのではないということを、ぜひ確認して説明していただくと。同じようになるわけではないというか、同じかもしれないですけど。変更がどうなるかわからないと言ったら言い方が変ですけれども。それから中学校なども、戸越台中学校と日野学園だけですけれども、ほかにも抽選の可能性も出てくるわけで、そういったこともあり得るということは、ぜひ確認しながら、そのときにお伝えしていただきたいと思います。"},{"i":58,"speaker":"若生学校制度担当課長","text":"まず、原案の「新制度の決定」というところが何をもってというところなのですけれども、あくまでも制度の全体像といいますか、学区域と学校選択制をこういった形で具体的に見直しますといった、施策としての決定を今年度中にと考えてございまして、その細かい学区域上の設定、要は町丁番でどことどこがどうという法規的な部分での規定につきましては、特に内規というか、法律や要綱等には落としていない部分でございます。ただ、学校選択制につきましては、一応、要綱という形で整理している部分がございますので、これは来年度、制度が施策として決定した後に、法令上の整備をしていこうと考えてございます。ですので、きちんとした、細かい整備につきましては、これはもう学校選択のほうに間に合うようなスケジュールでやっていきたいと思っています。\n学校選択等が変わることによって、中学校に関しても抽選等の可能性が出てくるというようなことは、もちろん、そういったことも必ず、制度としてやはり抽選というのは現状もあるものですので、そういったことはきちんと周知できるような形で、資料、パンフレット等に盛り込んでいきたいと考えております。"},{"i":59,"speaker":"高橋（し）委員","text":"ですから、決定というのは施策等の決定で決定ということなのですけど、それは教育委員会として決めると。それで、それが来年度になってから要綱に変えられていくという流れになっていくという説明だと、今、思ったのですが、何といいますか、決定したということ、これは今日をもって決定ではないわけですよね。ですから、そこのところがちょっとわからないのですみません。"},{"i":60,"speaker":"若生学校制度担当課長","text":"決定するというのは、教育委員会として決定していくということで、教育委員会の審議の中で、今年度中に制度を決定するといった手続きをとるということでございます。"},{"i":61,"speaker":"高橋（し）委員","text":"ということは、教育委員会の中の会議で、来年度の学事制度はこうしますということを教育委員会で決定して、そこで決定という理解でよろしいですね。それが今年度中ということで。それで、決定はしていないけども、説明とか、そういうのはしていくということですよね。"},{"i":62,"speaker":"篠田学務課長","text":"要は、教育委員会の権能として学区域の設定等がございますので、そちらは最終的に、今回、原案を出させていただいて、地域に対してご説明をさせていただく。また、それが結果的に、例えば地域の状況によって、何か手を打たなければいけないところが出てくれば、また改めて、細かい部分の見直し等はある可能性があります。ただ、最終的には、教育委員会として、学区域を更新する。今まであったものをこうしますというのを、最終的に教育委員会の権能として決定していくといったことが今年度中に行われるということでございます。"},{"i":63,"speaker":"高橋（し）委員","text":"そうなのです。今お話があったように、そこの調整のところで、また変わってくる可能性があるという話でした。そういう時にそれはもう一度、こちらに出てくるのでしょうかということなのです。もう一度、委員会で言っていただいて、今回、原案はこうでしたけれども、ここを少し変えて、教育委員会で決めていきますというお話をしていただけるのかというところをお伺いしたいです。"},{"i":64,"speaker":"篠田学務課長","text":"基本的には、権能としては教育委員会の権能でございますけれども、当然、文教委員会のこの場においても、いろいろ、もし変わるようなことがあれば、最終的にはご報告をさせていただいた上で、教育委員会で決めていくという段取りになろうかと思います。"},{"i":65,"speaker":"塚本委員長","text":"ほかにご発言等ございませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":66,"speaker":"塚本委員長","text":"ほかにないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(3) 平成３０年特別区および東京都人事委員会勧告の概要について"},{"i":67,"speaker":"塚本委員長","text":"次に、(3)平成３０年特別区および東京都人事委員会勧告の概要についてを議題に供します。\n本件につきまして、理事者より説明願います。"},{"i":68,"speaker":"熊谷指導課長","text":"それでは、平成３０年特別区および東京都人事委員会勧告の概要について報告いたします。\n本件は主に、区の行政職員にかかわるものでございますので、詳細については、本日開催されております総務委員会において報告されているものでございます。文教委員会に関するものとしましては、幼稚園の教員および固有教員がございます。なお、現在、幼稚園の教員が２８名、幼稚園の管理職が８名おりまして、固有教員につきましては２６名でございます。\nまず１ページをご覧ください。幼稚園教員にかかわる給与および手当にかかわる特別区の人事委員会勧告の概要についてご説明いたします。本年の人事委員会勧告は、平成３０年１０月１０日にございました。そのポイントなのですけれども、ページの一番上の四角で囲っているところにございます。１点目ですが、月例給につきましては、民間給与を上回っており、公民格差、月例で９,６７１円、割合にしましては２.４６％になりますけれども、これを解消するため、給料表の引き下げ改定を行うということでございます。第２点目に特別給でございますが、期末手当・勤勉手当につきましては、民間の賞与、いわゆるボーナスの支給月数を下回っているため、民間支給状況を勘案し、年間の支給月数を０.１カ月引き上げて、勤勉手当に割り振るというものでございます。これらの改定の結果、特別区の職員の平均年間給与は約１２万３,０００円の減額となります。\n続いて下の、II「改定の内容」に進みますが、行政職員の給料表につきましては、原則、給料表の全ての級および全ての号給について、給料月額の引き下げを行うということでございます。ただし、初任給については、人材確保の観点から給料月額を据え置きということになります。\n２ページにお進みください。幼稚園教員の月例給の給料表を含む、そのほかの給料表についてですが、行政職給料表との均衡を考慮した改定を行うこととされています。また、再任用職員の給料月額については、再任用職員以外の職員の給料月額の改定に準じた改定となります。特別給につきましては、先ほどご説明しましたとおり、年間の支給月数を０.１カ月引き上げるというものでございます。支給月数の引き上げ分につきましては、民間の状況等を勘案し、その全てを勤勉手当に割り振るものとしております。なお、特別区人事委員会による月例給の引き下げ勧告は平成２５年度以来でありまして、特別給の引き上げ勧告は５年連続となります。これら２点の実施時期でありますけれども、給料表の改定については、給与水準の引き下げを伴う内容の改定であるため、さかのぼることなく、改正条例の公布の日の属する月の翌月の初日、予定では平成３０年１２月１日から実施するということでございます。なお、平成３０年４月からこの改定の実施日の前日までの期間に係る公民較差相当分につきましては、平成３０年１２月に支給される期末手当の額において、所要の調整を実施するということでございます。\nそのほか、２ページ下段から３ページ、４ページにわたって、特別区人事委員会の意見が載せられておりますので、ご覧いただければと思います。\n続きまして、固有教員の月例給の給料表に係る勧告の概要についてご説明いたします。５ページ、そして６ページをご覧ください。こちらが「平成３０年職員の給与等に関する報告及び勧告」の詳細版からの抜粋になります。６ページの下のほうになります（３）「その他」の1)におきまして、区費負担の学校教育職員の給与制度については、「東京都の教育職員との均衡を考慮して、改定等を行うことが適当である」という記載がございます。これは、同じ職場で働く同じ職層の給与については均衡を図るという意味合いでございます。現在、区費負担の学校教育職員を置いているのは、特別区、いわゆる２３区の中で、品川区、杉並区、千代田区の３区となりますけれども、特別区人事委員会勧告の趣旨を踏まえ、東京都が定める教育職給料表と同内容の給料表を定めております。\n７ページをご覧ください。こちらは、東京都の平成３０年の人事委員会勧告です。平成３０年１０月１２日にございました。（２）比較の結果ですが例月給につきましては、民間給与をわずかに下回っており、公民較差で月例で１０８円、割合にて０.０３％になります。今年度の公民較差はわずかであり、給料表や諸手当において適切な配分を行うことは困難でありますが、有為な人材確保の観点から、初任給および給料表の初任層を較差の範囲内で引き上げたいということになっております。なお、特別区の勧告と東京都の勧告において公民較差に差異が生じますのは、民間給与の実態を調査する際の調査対象が異なることと、それから本年４月から実施された特別区人事給与制度の改正の影響によるものと考えられます。特別給につきましては特別区と同様で、年間の支給月数を０.１月引き上げるということでございます。そのほか、９ページから１０ページにわたって東京都人事委員会の意見が載せられておりますので、ご覧いただければと思います。"},{"i":69,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。"},{"i":70,"speaker":"南委員","text":"かなりの額、１２万３,０００円の減になるということで、相当な額であって、月相当にすると１万円ぐらい。この間、わずかですが、ずっと上がってきていたと思っていたのですけども、今回、こんなに大幅に下がるということは、人事委員会制度が変わった、最後に説明があったと思うのですけれども、改めてそこのところを、どう変わったのかを教えていただきたいです。こんなに大幅に額が下がるというのは、なかなか今までにない、額的には初めての金額ではないかと思っているのですけれど、公務員の皆さんに限らず、下がること自体、非常に影響が大きいのではないかと思うのですけども、業務委託、あるいはいろんな意味で仕事を委託している方々、非常勤採用の方々等々についても、公務員本人以外に影響がどのぐらいまで広がるのかというところを伺いたいです。"},{"i":71,"speaker":"熊谷指導課長","text":"まず月例給の公民較差、今回、下がった要因なのですけれども、人事委員会によると、平成３０年４月より実施した行政系人事・給与制度の見直しに伴う改正に伴って、職員構成に変化があったことによる影響と聞いております。それから、公務員以外というのは非常勤等でしょうか。これにつきましては、給料表によるものではございませんので、そちらについては今回の影響を受けるものではございません。"},{"i":72,"speaker":"南委員","text":"非常勤については影響がないということであれば、それはそれでよかったかと思うのですけれども、特別職や非常勤職員、場合によっては臨時職員、区関連団体の職員、委託労働者にも影響が及ぶ可能性もあるのではないかという見方もあるので、その辺について伺ったのですけれど、本当に影響がないと捉えているのか、もう一度、確認したいと思います。\nそれで、月額１万円減るということは相当なダメージだと思うのですけれども、そのことによって、消費がずっと落ち込んでいる中で地域経済に及ぼす影響も、やはりこれは深刻になってくるのではないかと思います。とりわけ年末に向かう時期、消費拡大が見込まれるときに、そういう状況になってきているということと、来年は消費税が１０％に増税されるという点で、本当にかなり深刻ではないかと私は思うのですけれど、そういう心配についてはどういうふうに受けとめているのか伺います。"},{"i":73,"speaker":"熊谷指導課長","text":"まず、１番目のご質問でございますけれども、今回は人事委員会勧告を受けて、区の職員の給与制度、給料表の改定ということになりますので、実際は本日、総務委員会で議論されているというところでございますけれども、非常勤等につきましては、今の段階では、今回のこの改正とは異なるものでございますので、今の段階では影響ないということでございます。\nそれから２番目なのですけれども、勧告内容としまして月例給について大幅な引き下げ幅となっていますので、非常に厳しい内容と受けとめているのですけれども、ただ、公務員の労働基本権の代償措置として社会一般の情勢に適応できるよう確保するものとして、人事委員会の勧告が法令により制度化されているものと思われますので、非常に厳しいですけれども、公務員としていたし方ない部分もあるとしか申し上げられないと思います。"},{"i":74,"speaker":"南委員","text":"総務委員会で議論されることだということなのですけれど、この委員会にも大きな影響というか、かかわりがあるというところで報告に上がっているわけですけれども、それを聞いた上では、やはりこういう人事委員会勧告制度というのが歴史的なところで出てきているというところは承知していますし、本当は労働三権がきちんと保障されて、公務員といえども外国のようにいろいろ交渉権だとかストライキ権だとか確保されるのが当たり前だと思っているけれど、それを奪われた上での人事委員会勧告制度で、しかもこういう不当と言ってもいいと思うのですけれど、やはりそういう状況の中で、本当にこれは、私としては承服しかねる。報告ということであっても、かなりひどいのではないかと思っていることはお伝えしておきたいと思います。"},{"i":75,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":76,"speaker":"渡部委員","text":"意見だけ述べます。今回、官民較差というのが、いわゆる景気動向によるものではないということで、いわゆる給与表の読みかえだという話は伺いました。それを、今年の４月にやるときに、私たちもそこをスルーしていたのはいけなかったのだと思うし、逆に人事委員会勧告もここまでわかって、それを平成３０年４月にやってきたのかというのも思いました。それで、いわゆる現給保障のルールがあって、一回、１級・２級を統合してしまうというところがあるから、２級だった人が１級に戻ってというところの中で現給保障されている。実は現給保障されてしまっているから、その人たちの分の給料が高いから、みんなで割りましょうというのが、どうしても納得できないです。だって、自分が希望して、民間だったら降格した人の給料を、何で、頑張っている人の分から、護送船団方式でみんなで下げなければいけないのかというのは、非常にひっかかります。当然これは、労使交渉で妥結したら、私たちも多分、招集がかかって臨時会を開いてというような感じになるのだと思うのですけれども、これはこのまま妥結しても、私たちははっきり言って、条例を通すかわからないです。どう考えても、「十何万、給料が下がります」、「はい、そうですか」とならない。多分、みんな心の中で、公務員とはいえ、「ちょっと待ってくれよ」と思っていると思うんです。いや、みんな思っていますよ。\nだから、今日は文教委員会ですから、総務委員会でどういう議論があるかわからないのですけれども、多分、私たち、これのみというわけではなくて、当然、そうなるのはやむを得ない部分で、労使が妥結してしまえばそれまでなのでしょうけれども、それが、さっき言ったように、１２月の賞与で一括、がつんとされたら、大変な人は大変だと思います。だから、それがどういうふうに傾斜がかけられるのかとか、これはしっかり、区長部局のほうからだと思うのですけれど、人事委員会勧告のほうにまた戻していただいてとか、今回、報告が出たから、その報告を私たちは聞くのは聞きますけれども、このまま通していいのかなという気だけはしています。意見だけ言っておきます。"},{"i":77,"speaker":"塚本委員長","text":"ほかにご発言はございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":78,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(4) 平成２９年度指定管理者による管理に対するモニタリング・評価の結果について"},{"i":79,"speaker":"塚本委員長","text":"次に、(4)平成２９年度指定管理者による管理に対するモニタリング・評価の結果についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":80,"speaker":"横山品川図書館長","text":"では、私からは、平成２９年度品川区立図書館の指定管理者による管理に対するモニタリング・評価の結果についてご報告申し上げます。平成２７年度から平成３０年まで、品川図書館以外の９館の図書館は指定管理にいたしておりました。３館を１グループにして３グループで、指定管理者はいずれも、しながわＴＲＣ・ウーヴグループのＪＶ共同企業体です。資料が同形式で３枚ございます。\n１枚目がＡグループで、荏原・ゆたか・源氏前図書館です。設置目的、指定管理業務の概要、運営実績も記載のとおりで、若干の減傾向です。総括欄では、地域連携事業について評価しております。東急電鉄、大崎高校との連携での区政７０周年記念事業を行っております。また、改善が必要とされた原因分析および対応方針とあわせて、接遇のさらなる向上と書架管理の改善を求めております。裏面に移りまして、１「区民満足の視点」では、利用者アンケートの実施結果を記載しております。おおむね、昨年比サービス向上の回答をいただいております。２「予算執行（財務）の視点」は、おおむね予定どおりの執行でございました。３「サービス向上および業務改善の視点」では、認知症サポータ養成講座研修を受講する試みがございまして、Ｂ・Ｃグループとともに全スタッフが受講したものです。この受講が今年度の高齢者支援事業につながってきております。４「組織管理体制および業務の適正執行の視点」では、各担当の設置とともに、危機管理巡回スタッフの配置等の工夫が見られます。経営会議での評価結果は、研修等で接遇向上に努め、グループ間の連携で、利用者へのさらなる利便性の向上に取り組む工夫が見られております。\n続きまして、２枚目がＢグループで、大井・南大井・八潮図書館です。設置目的、指定管理業務の概要、運営実績等、Ａグループ同様になっております。総括欄では、地域連携事業について評価しております。品川歴史館での講演会、しながわ水族館との連携展示、八潮学園メディアセンターとの連携等を行っております。また、改善が必要とされた原因分析および対応方針とあわせまして、混雑時の対応等、接遇のさらなる向上と書架管理の改善を求めています。また、裏面に移りまして、１「区民満足の視点」では、利用者アンケートの実施結果、Ａグループ同様、昨年比サービス向上の回答をいただいております。予算執行はおおむね予定どおりでございました。３「サービス向上および業務改善の視点」では、Ａグループ同様、認知症サポータ養成講座研修を受講しております。４「組織管理体制および業務の適正執行の視点」でも、同様に、各担当の設置とともに危機管理巡回スタッフの配置等の工夫が見られます。経営会議での評価結果はＡグループ同様でございました。\n３枚目がＣグループで、五反田・大崎・二葉図書館になります。設置目的、指定管理業務の概要はＡグループ同様になっております。総括欄で、地域連携事業について評価しております。大崎図書館移転準備を品川図書館グループ連携で減らし、平塚共同書庫の運営を開始したことを記載しております。また、改善が必要とされた原因分析および対応方針とあわせて、二葉図書館の手にとりやすい書架づくりの工夫を他館へつなげるべく記載してございます。裏面に移りまして、１「区民満足の視点」では、同様に利用者アンケートで良好な結果をいただいております。予算執行についてはおおむね予定どおりでございました。３「サービス向上および業務改善の視点」では、同じく認知症サポータ養成講座研修を受講している試みがございました。４「組織管理体制および業務の適正執行の視点」では、スタッフの配置の工夫が見られます。経営会議の評価結果は、Ａグループ、Ｂグループと同様でございました。"},{"i":81,"speaker":"廣田子ども家庭支援課長","text":"私からは、子ども未来部が所管する施設のうち品川区立家庭あんしんセンターについてご説明申し上げます。おめくりいただきまして、シートをご覧ください。\n指定管理者は、社会福祉法人福栄会を指定しております。設置目的については、母子家庭の自立生活支援および子育て家庭に対する育児支援を図るものでございます。指定管理業務の概要につきましては、児童福祉法で定める母子生活支援施設である、ひまわり荘、子育て支援センター、ファミリー・サポート・センターによる事業運営およびショートステイ室、トワイライトステイ室の利用等に関すること、また施設の維持管理に関することでございます。管理運営の実績については表でお示しのとおりでございます。\n次に、総括で積極的に評価した事項についてでございますが、平成２８年度より地域貢献活動事業として、立正大学のＢＢＳサークルを活用しまして大学生ボランティアによる学習支援事業を行い、食事の提供と居場所づくりに取り組んだことを評価しております。また、利用者の拡大を図るための努力もしているというところを取り上げてございます。その他、ショートステイ等の利用につきましては、レスパイトに対する支援についても追加して行ってございます。また、ファミリー・サポート事業については、養成講座を行い、新規登録会員を増やしているというところに取り組んでおります。また、マッチングができない事例についても集約し、課題の検証を行ったところでございます。改善が必要な事項につきましては、個人情報保護に関する情報セキュリティーの向上のための対策や研修の実施について、さらなる取り組みが必要というところを挙げています。その内容について取り上げた理由についてでございますが、家庭あんしんセンターにつきましては、各種業務におきまして、電算機器を使い業務の効率化が図られているところでございます。それに対し、個人情報の保護について、法人全体の課題としての取り組みはあるものの、家庭あんしんセンターの年間計画の中に研修が盛り込まれていないところなどから、今後の取り組みについて定期的に取り組むよう申し入れをしているところでございます。また、今後の対策につきましても、サイバー攻撃等が激化する中でというところで、セキュリティー対策について取り組んでいくことが必要ということで挙げております。\n裏面をご覧いただきまして、区民満足の視点に対する取り組みですが、こちらにつきましては、各事業実施時にアンケートを行い、また施設内に意見箱を設置するなど、利用者の意見を聞く努力をしております。苦情解決第三者委員会というものを設置しておりますが、平成２９年度については苦情の申し入れはなかったという状況でございます。予算執行につきましては、管理運営の委託料等および人事配置につきましては、決算書等で適切に計画的に執行されているということを確認しています。\nサービス向上における業務改善の視点でございますけれども、それぞれの事業ごとに目標値を設定し、平成２８年度より３カ年計画というのを立てて、達成に向けて常に取り組んでいるというところを確認しております。また、ひまわり荘では、退所家庭のアフターケアにも取り組んでいるというところで、着実な自立支援のサポートを行っておりました。また、ファミリー・サポート事業では、会員との交流会を行うほか、利用後にモニタリング電話という形で聞き取りを行いサービスについての意見を聞いているというところが、今後の活動に生かされておりました。\n組織管理体制および業務の適正な執行の視点でございますが、適正な職員配置や各事業の連携は図られており、調整を行いながら執行されている状況でございました。安全管理につきましては、荏原警察署等に依頼し、防犯講習の訓練にも取り組んでおりました。\n経営会議における評価結果でございますが、引き続き、利用者の拡大、利便性の向上を図るということと、退所者のアフターケアについても引き続き取り組むこと、また個人情報の取り扱いについての研修等に取り組むこと等管理体制の強化について努めることと言われております。"},{"i":82,"speaker":"吉田保育施設調整担当課長","text":"私からは、保育課の所管となります、ぷりすくーる西五反田のモニタリング・評価結果をご説明いたします。お手元の総括シートをご覧ください。\nぷりすくーる西五反田は平成１６年６月１日に開設しまして、指定管理者が特定非営利活動法人子育て品川でございます。設置目的は、小学校就学前の乳幼児に対し、保育園および幼稚園の相互の特色を生かした保育および教育を継続的かつ一体的に実施することにより、乳幼児の健全な育成を図るとともに、地域における子育て家庭の支援をすることでございます。\n次に、指定管理業務の概要につきましては、０歳児から２歳児までの保育園、３歳児から５歳児までの幼児教育施設、地域子育て支援センターにおける事業の運営等を行っているところでございます。\n事業の管理運営実績等につきましては、総括シートの中段の表をご覧ください。各利用者でございますが、ほぼ安定的に推移しているところです。管理運営委託料が、平成２８年度に比べまして６００万円ほど増加しているところでございますが、平成２９年度はキャリアアップ補助金が増加したことによるものです。\n次に、「総括」の欄をご覧ください。積極的に評価した事項といたしましては、引き続き、教育・保育課程や年間計画を定期的に見直し、よりよい保育の実践に取り組んでおります。次に、改善が必要な事項でございますが、保育士の確保は依然厳しい状況のため、今後も引き続き、職員の定着化、離職防止に向けて、職員の処遇改善に取り組む必要がございます。\n改善が必要とされた原因の分析および対応方針につきましては、優秀な人材を確保するため、各種補助金制度の活用や経費削減により財源を確保しまして、職員の処遇改善に引き続き取り組んでまいります。\n次に、評価の視点でございます。１「区民満足の視点」ですが、特色のある保育活動および施設運営を行っておりまして、平成２９年度の東京都福祉サービス第三者評価、これはホームページで公開されているものでございますけれども、９７％満足といった結果を得ております。２「予算執行（財務）の視点」ですが、効率的な施設運営および収入の確保に努めた結果、収支状況は安定しております。３「サービス向上および業務改善の視点」ですが、重点テーマおよび目標につきましては、国際理解教育をはじめとする特色ある保育・教育活動のさらなる充実を図られております。指定管理者からの提案といたしましては、ＮＰＯ職員の給与の昇給幅を見直すことによって、全体的な人件費の抑制を図るなど、経費削減に努めています。４「組織管理体制および業務の適正執行の視点」ですが、組織管理体制としましては、内部研修の充実に努め、職員のスキルアップに取り組んでおります。業務の適正執行では、事故、災害および非常時対応の昼夜訓練強化のほか、保護者による送り迎えの際に、カード式のセキュリティシステム導入により、安全安心の向上、迅速な対応など、園におけるより一層の安全確保に努めているところです。また、個人情報の保護および法令遵守の観点から、日常業務における個人情報の管理を引き続き徹底しております。\n以上、ご説明いたしました内容を踏まえまして、園運営は適切に実施されているものと認識しております。"},{"i":83,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。"},{"i":84,"speaker":"飯沼委員","text":"まず、図書館のところなのですけれども、職員の状況を知りたいのですが、職員数と職種と、あと正規・非正規の人数、司書がどのぐらいいるのか、３つのグループでいいのか。所管ごとに違うのか、どういう聞き方がいいかわかりませんが数字的なものを教えてください。本来であればここに載せていただきたいと毎回言っているのですけれど、聞かないとわからない中身なので教えてください。"},{"i":85,"speaker":"横山品川図書館長","text":"まず職員数ですが、品川図書館の職員数は３０名だけです。あとの図書館につきましては指定管理で、全て委託の形になっているため人数は分かりません。\n今、ちょうどモニタリング調査をしておりまして、細かな数字を出していただいておりますので、細かな数字、日々動いているような形になってしまいますが、ご用意できたらお届けするような形にしたいと思います。"},{"i":86,"speaker":"飯沼委員","text":"委託の部分は、ではわかったら数字で教えてくださるということで、ぜひ司書の方がどの程度なのかという中身もわかるのでしょうか。"},{"i":87,"speaker":"横山品川図書館長","text":"指定管理の条件としまして、半数程度以上、確保してほしいという要望を出しております。それに対応しまして、指定管理の提案で、５割、６割という提案をいただいておりますので、今現在もそれ以上を確保してございます。"},{"i":88,"speaker":"飯沼委員","text":"図書館法とか、あと民間のところ、図書館協会などでも、とにかく司書を中核とした運営が大事であると求められているので、その辺はやはり大事にしていただきたい、確保していただきたいと思います。\nあと、都度、求めているのですけれども、利用者の意見を取り入れたり、知識人とかいろいろな方々の意見を一緒に地域とともに考えていくという意味で、図書館協議会。多分、品川区はずっとないと思うので、ぜひこの設置を求めたいのですが、いかがでしょうか。"},{"i":89,"speaker":"横山品川図書館長","text":"ご要望いただきまして、検討が適切かどうか、また品川区の土地柄に合うかどうかも含めまして検討中でございます。また、地域とのかかわりにおいて、この間、いろいろな地域に赴いてお話しさせていただく中で、各地区の図書館長が中に入っていろいろなことをすることで、地域の方とのかかわりも持っている状態なので、委員会という形が適切なのかどうかは引き続き検討していきたいと思っております。"},{"i":90,"speaker":"飯沼委員","text":"利用者の立場の意見も十分聞けるという意味で、図書館協議会ができているところは、すごく有効に動いていますので、ぜひご検討をよろしくお願いいたします。\nあと、家庭あんしんセンターなのですけれども、家庭あんしんセンターは職員数、職種、正規と非正規についてもわかるでしょうか。"},{"i":91,"speaker":"廣田子ども家庭支援課長","text":"家庭あんしんセンターのうち、ひまわり荘につきましては、嘱託医を除いて、職員数１２名になっています。そのうち、保育士や福祉職が８名、あと調理の職員、事務の職員等がおります。その他、常勤・非常勤についてですが、おおむね常勤ですが、心理職、臨床心理士と、自立支援のための支援員ということで１名ずつと、事務員が１名。その３名が非常勤で、その他は常勤になっています。職種としては保育士が多いのですが、社会福祉士、社会福祉主事等が何人かずついます。\nファミリー・サポート・センターについてはアドバイザーしか置いていませんので、アドバイザーが３名で、保育士と社会福祉士と聞いております。"},{"i":92,"speaker":"高山子ども育成課長","text":"家庭あんしんセンターのうち、子育て支援センターにかかわります職員といたしましては７名おりまして、そのうち２名が常勤職ということで聞いております。資格といたしましては、介護福祉士や社会福祉士、精神保健福祉士などの資格を持つ者が常勤として勤務しております。"},{"i":93,"speaker":"飯沼委員","text":"あと、家庭あんしんセンターのところなのですが、中央のところに育児支援ヘルパーが平成２８年度から独自事業に変更となっているのですが、この中身をひとつ教えていただきたいです。裏面の苦情解決第三者委員会、平成２９年度は苦情の申し入れはなかったということなのですが、これは、どういう構成で委員会が設置されているのか、中身を教えてください。\n続けて、ぷりすくーる西五反田のほうにいきますが、ここのところ、ずっと、保育士の確保がなかなか難しいと。やはりここの施設の特有なところが含まれているのですかね。「幼保連携型認定こども園への移行に向け」とあるのですが、この辺の方向性とか、いつぐらいに移行できるのか、その辺も含めて教えてください。"},{"i":94,"speaker":"高山子ども育成課長","text":"私から、家庭あんしんセンターの表記上の、いわゆる独自事業としてというような注書きの補足をさせていただきます。こちらにつきましては、従前、養育支援訪問事業と育児支援ヘルパー事業を一体的に運営していたところですが、平成２８年度より、養育支援訪問事業につきましては、従前、いわゆるサービスのような性質のものではなく、ケースワークの必要性から、無料にてといいますか、自宅を訪問する事業ですので、これを、サービス事業であります育児支援ヘルパー事業と、それぞれ別々に記載することで、その性質を明確にしたといったことから、独自事業というような表記にさせていただいたものでございます。"},{"i":95,"speaker":"廣田子ども家庭支援課長","text":"家庭あんしんセンターの苦情解決第三者委員会なのですけれども、こちらにつきましては、家庭あんしんセンター独自というよりも、社会福祉法人として福栄会の中で、各施設について苦情が上がってきたものに対し苦情解決第三者委員会というものが設けられていると、理事会等で説明されていました。メンバーにつきましては、手元に資料がないのですが、常務理事や理事長が同席し、外部の委員等が入って、数名で構成されていたかと思います。"},{"i":96,"speaker":"吉田保育施設調整担当課長","text":"ぷりすくーる西五反田の認定こども園化の方向性がいつぐらいかということなのですけれど、これは今、検討している最中でございまして、まだはっきり、いつからなるというところは決定している事項ではございません。"},{"i":97,"speaker":"塚本委員長","text":"ほかにご発言ございますか。"},{"i":98,"speaker":"南委員","text":"図書館というのは、改めて私たち住民が読書したいという、読書する権利というか、あえて権利と使いたいのですけれども、あるいはいろいろな調査をしたりして、状況を知りたいという学習権とか、そういうことを保障する施設、機関ではないかと思っているのですが、まずそういう認識でいいのかどうかということを、１つ伺いたいと思います。"},{"i":99,"speaker":"横山品川図書館長","text":"図書館の幾つかの機能の中で重要な一つだと思っています。"},{"i":100,"speaker":"南委員","text":"図書館法という法律があるわけですけれども、詳細に見ているわけではないのですが、その第１４条に、住民参加の保障として図書館協議会の設置をすることが求められていると思うのです。そういう点で、先ほど飯沼委員の質疑の中で、利用者協議会というのですか、その問題については、土地柄必要なのかどうかということも含めて研究したいとおっしゃったのですけれども、私は、法律との関係で言うと、設置を求めている。こういうふうに利用者協議会があると思うのです。そういうことからすると、土地柄、必要なのかということではなくて、もう設置することが必要だというふうになっているわけで、研究という遠い将来に持っていかないで、ぜひ検討して設置できるように、来年度からでもいいですけれども、そういうふうにするべきだと思っているのです。その点についてどういうふうに思うのでしょうか。\nなぜかというと、図書館というのは、図書館長の設置機関とか意見具申機関とか、あるいは同時に、教育委員会の附属機関というふうに位置づけられている、組織的なところから見てそういうふうになっているわけですから、そこで住民が、やはりいろいろな例えば資料が欲しいとか、こういう資料も備えてほしいとか、そういうことだけではなくて、図書館の運営に対しても、いろいろと地域の要求を受けとめられるような協議機関というのは重要だと思うのです。そういう点で、ぜひ具体的に設置できるように努力していただきたいと思うのです。そのことについての見解を１つお願いします。\nそれから、３グループの報告がそれぞれされたのですけれども、改めて去年とどういうふうに変わっているか、去年の議事録も見たのですが、改善が必要な項目というところで、昨年度と引き続きということなので「平成２８年度に引き続いて蔵書管理についてはスキルアップを必要とします」と、図書館長が説明しておられるのです。その原因の分析および対処方法としては、スタッフとの意見交換云々と書いてあるのですけれども、今回のここのモニタリングのところでも、蔵書とか蔵書管理というところについては、やはりスキルアップが必要だというふうになっているのです。だから、この間、少なくとも２年にわたって、そういう指摘がされてきている中で、どういうふうに改善しているのかという認識を持っているのか伺いたいと思います。"},{"i":101,"speaker":"横山品川図書館長","text":"委員ご指摘のとおり、利用者協議会については図書館法で一応、望ましいという形で表記されておりますので、品川区においても引き続き検討は進めさせていただきます。ただ、地域との兼ね合いについては、先ほどご説明したように、各図書館長が地元に出向いて、いろいろ意見交換をしながら、事業展開をしているような状況がありまして、それをわざわざ委員会に持っていくことが適当かどうかも含めまして、引き続き検討させていただきたいと思います。\nそれと、改善点の蔵書管理についてですが、こちらについては、地域ごとの蔵書構成と、地域の資料等の扱いがございまして、やはり長い経験に基づいて今まで管理していたものを、三年、四年といったような短いスパンで事業者が全部やるのは、非常に不可能なところがございます。また一方、職員も入れかわりがあるような状態で、ほとんど長い経験がある者がいないような状態があり、お恥ずかしい話ではございますが、そういう点で、一つひとつの判断に手間取るというところで、日々、新しい本が入ってくる中で、本があふれてしまうような状況も多々見られるところを、どのように改善していけばいいか、事業者と協働して考えながら、これからもまた進めていきたいと考えているところでございます。"},{"i":102,"speaker":"南委員","text":"利用者協議会の関係で、図書館長が地元に出向いて聞いているという話なのですけれども、やはり私は、図書館ごとに地域の声を全体でつかみ、地域と図書館側の職員とで共有していくということが大事だと思うのです。だから、そういう点で、図書館長が地域に出向いていくからいいというふうにはならない。全然そこの質が違うと思うので、やはりここは、早急にどういうものかというのを、いろんな自治体のところの研修も検討もしていただきながら、できるだけ早期に利用者協議会を設置していただきたいということは、強く求めておきたいと思います。\nそれと、選書・蔵書管理の関係ですけれども、いみじくも職員の入れかわりだとか、経験の浅い職員とおっしゃったのですけども、だったらなぜ指定管理にしたのでしょうか。ずっと図書館を直営でやっていたときに、やはり図書館が好きで、図書館にずっと長く勤めていたいという職員も何人もおられました。そういう状況の中で、あえていいますけれども、ばっさりとそういう声を削って指定管理者制度を導入して、今日のような、何年にもわたる、選書や蔵書管理のスキルアップが必要だというふうな、そういう状況の中で区民にサービスを提供している。十分なサービスになっていないということを私は想像するので、問題意識を持ったわけです。ですから、やはりこういうことが長く指摘されて、指定管理者制度を導入してから今年で４年目ですか。たしかそんな状況で変わりましたよね。これだけのモニタリングをやって、同じような状況が出るということはいかがなものかと思いますので、やはり指定管理というのはやめて、経験豊かな職員による地域住民との、いろんな本に対するカンファレンスとか、そういうことも対応できるような、そういう中身で事業を運営していくべきだということを、つけ加えておきたいと思いますし、判断に手間取るというところについては、所属長としてどういうふうに認識を持っているのか、改めてそこも伺っておきたいと思います。"},{"i":103,"speaker":"横山品川図書館長","text":"委員ご指摘の、直営がよかったという点につきましては、平成２７年度の導入時点で既に、経験が長い職員があまりいないような状況で、それであれば、民間の司書の資格を持ったところに助けてもらって一緒に運営したほうがいいという判断で、指定管理を進めたという経緯があったように私は聞いております。\nそれと、今、蔵書管理について引き続き何度も指摘がされている点につきましても、先ほどもご説明しましたように、事業者と職員と協働しまして、一つひとつ、どんなやり方が適しているかというのを進めながら、また、本そのものについても、これから電子化が進む中で、どういう状況で蔵書管理していったほうがいいのかというのを引き続き検討していきたいと思っております。"},{"i":104,"speaker":"南委員","text":"大変、残念だと思います。その理由は、今の答弁にもあったのですけれども、やはり地域の声を受けとめるという姿勢もなく、働いている職員の図書に関する知識、司書の状況も６割から７割いるという話なのですけれど、それにしてもあまりにも選書・蔵書管理が、ずっと長く指摘が出るような事態になっているということ。やはり、これは本当に住民サービスという点では、大きくマイナスになっている状況ではないかと思うのです。あまりにも区の姿勢、教育委員会としての姿勢が、図書館を軽視しているのではないかということを指摘しなくてはいけないというぐらいの実態になっているということは、非常に残念だと思います。そういうことを指摘して、少なくとも短期間の間に、改善を求める点についてはきちんとレベルアップしていけるようにしていただき、指定管理にこだわらずに、やはり住民サービスというところをとって、指定管理という制度を導入したということについてもきちんと検証するべきだということを言って終わりたいと思います。"},{"i":105,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":106,"speaker":"石田（し）委員","text":"まず図書館ですけれども、これは利用者数が減っている中で、このシートには、その点に関して何も記載がない。業務改善に関しては、いろいろ防災訓練に参加したり、地域に根づいた活動をしたりと、利用者サービスが向上しているように理解はするのですが、利用者数について各指定管理者たちはどのように捉えているのか、把握していたら教えてください。"},{"i":107,"speaker":"横山品川図書館長","text":"実は、図書館全体での利用数は増えておりまして、原因としては２点ございます。１つは、視聴覚資料の大幅な減少。もう一つが、取り次ぎ施設での扱いの増加です。１点目の視聴覚資料につきましては、ＣＤが昨年比で１万８,０２１枚減というような形で、ほとんど使われなくなっています。これは、全体の状況なのか、図書館だけの状況なのか、はっきり数値では確認できませんが、おそらくはＣＤから別の媒体へ移っているということのあらわれではないかと思っております。また、取り次ぎにつきましては、昨年から１万６,６８３冊の増加が見られます。そちらでも図書館１館分のものを取り次ぎで扱っている形になっておりまして、平成３０年度については、目黒のサービスコーナーと、大崎駅西口から１年分の数値が入ってくるので、もっと大きな形の扱いになると思います。そういう意味で、図書の読み方が全然変わってきているというのを感じておりまして、そちらが原因と判断しております。"},{"i":108,"speaker":"石田（し）委員","text":"それでは、いろいろ時代が変わって、区民の方たちのいわゆるニーズも変わってきているというのを把握しているにもかかわらず、これまで何も電子図書に関して、このシートにも出てこないですし、図書館長のお話の中でも、研究をするというのにとどまっている。利用者のニーズをそこまで把握しているにもかかわらず、なぜ、いまだに検討段階にも入ってこないのか教えてください。"},{"i":109,"speaker":"横山品川図書館長","text":"電子書籍につきましては、各区の状況等もお聞きして、参考に渋谷区にも取材をさせていただいているところですが、まず、ちまたに販売で出回っている電子書籍については、図書館で利用する場合には著作権の調整が必要です。そういう意味で、実際に使える書籍が５,０００件程度という形に渋谷区ではなっているそうです。ほとんど著作権フリーになったものなので、新しいものを求める電子書籍の主たる需要者に対して対応していない状況があるのと、電子書籍の利用が所有権ではなくて、２年間もしくは５２回貸し出しで権利が消えるという貸し出しの方式になりますので、図書館としては、今まで所蔵していたというのと財産の考え方が違ってしまうので、正式に踏み出すことについては、やはり詳細な検討が必要ということがありますので、いまだ検討段階でございます。また、新しいニーズにつきましては、この間、Ｗｉ－Ｆｉ等について、かなりお声をいただいておりますので、具体的な検討をこれから進めていくような形で、新しいものの需要に対しても敏感に反応するよう努めております。"},{"i":110,"speaker":"石田（し）委員","text":"ぜひよろしくお願いいたします。\n家庭あんしんセンターですが、数字と合っているかどうかわからないですけれども、私のイメージでは、母子家庭というのは年々増えているのかなと思います。違ったら違うと言っていただきたいのですが、それにもかかわらず、こちらも来館者数等々は減っているように、このシートでは見えるのですが、この辺の要因というのが何なのか、このシートを見る限りだとわからないので、担当課として把握されていたら教えてください。"},{"i":111,"speaker":"廣田子ども家庭支援課長","text":"母子家庭の数なのですけれども、手当の数から言うと、子どもの数が増えているわりには横ばいという形です。ただ、手当を受けているのは、所得がある一定程度以下なので、全容はわからないので、増えているか減っているかというところについては押さえ切れていないというところです。\n来館者数については、ひまわり荘に入っている人たちは、ここの数には含まれておりませんので、来館では反映されておりません。入所者については、全体で定員２０世帯のところで、現状、９世帯２１人なのですけれども、２年で自立させていくという目標を立てているので、もちろん短い方も長い方もいらっしゃいますけれども、順調に出て回転しているというところです。ニーズといいますか必要と思われる方はたくさんいらっしゃって、入所相談は平成２９年度で３６件ほど受けているのですけれども、ペットを飼いたいとか、入所される方の要望がすごく高くて、ひまわり荘には入らないというところで、見学に来たのが３６件のうち３世帯で、入ったのが１件というような状況で、入ったほうが自立できるのにと思うのですが、なかなか入らないというところで、今後どうしていくかという課題があります。それで、来館者数については、いろいろな事業や相談の利用者が入館者数になっておりまして、各種事業については利用は減っていないのですけれども、ふらっと訪れる人が少し減っているというところです。"},{"i":112,"speaker":"石田（し）委員","text":"こちらも時代とともにいろいろニーズが増えてきているのかと思いますので、どこまで対応するべきかというのは、もちろんあるのかと思いますが、それはうまく運営、いわゆる指定管理の方たちと話をしていただきながら、工夫できるところは工夫していただければと思います。\nあと、このシートだと、運営の委託料というのが、若干ですが減っています。私のイメージだと、それこそ母子家庭の支援というのは、年々必要なものが多くなってきているという認識なのですけれども、運営費が減っている理由というのが、もしあるのであれば、そこだけ教えてください。"},{"i":113,"speaker":"廣田子ども家庭支援課長","text":"運営費については、ひまわり荘等については２０定員で、今、暫定定員が１３定員にされてしまっているのですけれども、いつ入ってもいいように２０定員分、規定のとおりにお支払いをしているところです。ここで差異が出てしまうのは、平成２８年度だと、例えば第三者評価を外部委託した委託料であるとか、あと、３年に１度の定期点検であるとか、工事のお金が入ると上下するようになっていて、ほぼ人件費と施設管理なので、おおむね、人がたくさん入っても入らなくても同じ金額は指定管理者に渡している内容です。ですので増減は、工事であるとか、特殊な、その年度にやらなければならない要因です。"},{"i":114,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":115,"speaker":"高橋（し）委員","text":"ぷりすくーる西五反田のほうでお尋ねしたいのですが、先ほど幼保連携型認定こども園についてはお話があったのですが、今年の１月の文教委員会で社会福祉法人化の準備ということでシートが配られて、それで、このままではそれができないので環境整備を検討するというお話だったのですが、具体的にどこをどう検討し、どこに問題があって社会福祉法人化できないのか。まず認定こども園の前にそれができて、平成３１年に社会福祉法人化ができるのかというところの準備状況を含め、ご説明いただきたいと思います。\nその前に、指定管理ということで、ここに「積極的に評価した事項」とありますけれども、もうこれはまさに指定管理で、公設民営で、利用者の方が非常に満足し、住民サービスの向上につながっていますから、指定管理の成果だと思います。指定管理の導入の非常にいい成功例だと思っております。"},{"i":116,"speaker":"吉田保育施設調整担当課長","text":"今の具体的なスケジュール、社会福祉法人化に向けた具体的な内容の点のご質問かと思っております。社会福祉法人化とあわせまして認定こども園化するところに当たり、幾つか現状の施設においての課題がございます。現状の施設ですと、園庭の面積が足りないだとか、そういう面がございます。その辺のところを、どうやって今後解決していくかというところと、認定こども園化に当たっては、その運営母体として社会福祉法人という形になりますので、認定こども園化の時期に合わせた形での社会福祉法人化を今予定しており、１月２２日の文教委員会では、平成３１年度からの社会福祉法人化を予定とご説明申しあげたところではございますが、現在、平成３２年からの社会福祉法人化を予定としているところでございます。"},{"i":117,"speaker":"高橋（し）委員","text":"今、平成３２年に社会福祉法人化。認定こども園化に合わせてという話なのですけれど、先ほどの設備などは、平成３１年までだったら新しい改正によって経過措置だったので、さまざまな条件の中で緩和されていたのですが、それをもう超えてしまうというところから、社会福祉法人化せざるを得ないという話になっているのだと思うのです。それで社会福祉法人化するときに、社会福祉法人については福祉の部署がありますけれども、そちらのほうとの連携をどのようにしているかということと、平成３２年に社会福祉法人化するということは、来年の初めぐらいには、もう社会福祉法人化の申請をしなければいけないのではないだろうかと思うのです。ということは、もう今からさまざまな条件整備をして、１カ月で社会福祉法人化ができるというのではないと思うので、そういう意味では、現状の社会福祉法人化の準備はどういう感じなのかを伺いたいと思います。"},{"i":118,"speaker":"吉田保育施設調整担当課長","text":"現在、社会福祉法人につきましては、新しい社会福祉法人ということで考えているところでございます。それと、社会福祉法人の申請の時期などにつきましては、今のところ、平成３１年度の中ほどで予定しているところでございます。"},{"i":119,"speaker":"高橋（し）委員","text":"平成３１年度の中ほどに社会福祉法人化の申請をするということですので、今、準備を進めていっていただいているところだと思うのです。認定こども園化を進めて、公私連携幼保連携型を進めていっていただきたいという話の中でお話ししているので、ぜひスピーディーにやっていただきたいという趣旨でお話をしています。それが少しずつおくれているのではとても残念なので、ぜひこのスケジュール、現状でもそういうところなのでしょうけれど、進めてください。\nそうすると、今の、特定非営利活動法人子育て品川の指定管理は今年度で終わると思います。今度どこになるかというのは、プロポーザル等だと思うのですけれども、そうすると、社会福祉法人化し、そしてその後、認定こども園化していくという条件がプロポーザルの中にあり、子育て品川も含め、プロポーザルあるいは指定管理の選考をしていくのかと思うのですが、そのあたりの来年度以降の指定管理の話についてご説明をいただきたいと思います。"},{"i":120,"speaker":"吉田保育施設調整担当課長","text":"現行のぷりすくーる、これで１５年目になりますけれども、指定管理、第３期目は今年度で終わります。第４期目につきましては、選定委員会を新たに開きまして、その中で選んでいくという形を、予定しているところでございます。"},{"i":121,"speaker":"高橋（し）委員","text":"そのときに、やはり、今お話にあった社会福祉法人化や認定こども園化というところの評価とか、そういったことも含めて選定委員会が開かれて決まっていくのかということが知りたいのですが。"},{"i":122,"speaker":"吉田保育施設調整担当課長","text":"社会福祉法人化はまだすぐできるわけではないのと、現在の、今のぷりすくーるは、来年の３月で指定管理の第３期目が終わります。この後、第４期目の選定は、その辺を含めまして、今後、調整します。その後、社会福祉法人化というのを考えているところでございます。"},{"i":123,"speaker":"高橋（し）委員","text":"非常に成果のある事業を行っていただいていて、子育て品川もしっかりやっていただいていると思います。ただ、仕事をされている方々が、この先どうなるのだろうといった面で、先が少し見えない中での不安をお持ちの方もいらっしゃるということもありますので、ぜひ、今お話があったように、新たな認定こども園化に向けて、先が見えるような形で区も支援して、バックアップしていただきたいと思います。これは要望です。"},{"i":124,"speaker":"塚本委員長","text":"ほかにご発言はありますか。"},{"i":125,"speaker":"飯沼委員","text":"検証・管理のところなのですが、見直してみたら、管理運営委託費の記入欄がなくて、ほかのと比べると年度の変化がわかるのですが、予算書を見たら、地区図書館の委託費というのは６億８,４３８万円。これはグループに分かれているから載せにくいのかどうか、ぜひ委託の費用もわかったほうがいいので、今日は結構ですが、次回からぜひ、ここに載せていただきたいという要望が１点です。\nあと、先ほど職員の人数をお伺いしたら、品川図書館は３０人ということでした。この中で、司書資格を持っていらっしゃる方がいらっしゃるのかと、あと、予算書を見たら３２人になっているのですが、減員になってしまったのか、気になったので教えてください。"},{"i":126,"speaker":"横山品川図書館長","text":"まず、品川図書館で司書資格を持っている人は、実質１人になります。\nあと、人数については、調査時点の差だと思います。休職等で出入りが激しいものですから、申しわけないです。"},{"i":127,"speaker":"飯沼委員","text":"司書については、今の課長の責任ではないのです。品川区が、ずっとこの間、直営でやってきたときから司書資格を軽視していたというか、必要がないということで、資格を持っていた人をみんな外に、一般の事務に異動させているのです。そういった点で、先ほどの指定管理のところには、半分以上ですか、司書を置いているということなのですが、やはり図書館というのは本当に教育的な場であり、専門職がとても大事という意味で、ぜひ司書の役割をきちんと位置づけた図書館運営をしていただきたい。そういった面では、品川図書館においての司書の役割というのはとても大きいと思うのです。ここはぜひ改善していただきたいと思います。よろしくお願いします。"},{"i":128,"speaker":"塚本委員長","text":"ほかにご発言はないようですので、以上で本件を終了いたします。\n会議の運営上、暫時休憩いたします。\n○午後 ０時３６分休憩\n○午後 １時３５分再開"},{"i":129,"speaker":"塚本委員長","text":"それでは、ただいまより文教委員会を再開いたします。\n────────────────────────────────────────────\n(5) 保育料に係る寡婦（夫）控除のみなし適用について"},{"i":130,"speaker":"塚本委員長","text":"(5)保育料に係る寡婦（夫）控除のみなし適用についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":131,"speaker":"佐藤保育課長","text":"それでは私から、保育料に係る寡婦（夫）控除のみなし適用についてご説明いたします。\nまず、１「概要」ですが、子ども・子育て支援法施行令の一部を改正する政令等の公布に伴い、地方税法上の寡婦（夫）控除が適用されない未婚のひとり親について、同法の寡婦（夫）とみなした上で、保育園保育料等の賦課に必要となる住民税額を算出することで、ひとり親家庭の支援の充実を図るものでございます。これまで、区の保育料については、児童扶養手当を受給している世帯までをみなし寡婦（夫）の適用範囲としてまいりましたが、今回、政令が公布されたことから、地方税法と同様の取り扱いに変更するものでございます。具体的には、例えば扶養親族が１人の場合、これまでは所得金額が２３０万円未満までの世帯については、みなし寡婦（夫）の控除を適用していましたが、今後は地方税法と同様に、所得金額にかかわらず控除を適用いたします。したがいまして、対象範囲を拡大するものでございますが、実際に該当する世帯としましては、これまでの対応件数等々からごくわずかになるものと見込んでおります。\n次に、２「対象施設」ですが、（１）から（４）の施設となります。適用日は平成３０年９月１日からとなりまして、ホームページやポスター等で周知を図っております。"},{"i":132,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。\n〔「なし」と呼ぶ者あり〕"},{"i":133,"speaker":"塚本委員長","text":"特にございませんか。\nご発言がないようですので、以上で本件および報告事項を終了いたします。\n────────────────────────────────────────────\n２ 所管事務調査\n次世代教育について"},{"i":134,"speaker":"塚本委員長","text":"次に、予定表２ 所管事務調査を議題に供します。\n本日は、７月３日の委員会において決定しました所管事務調査項目のうち、次世代教育についての調査を行ってまいります。本日は、まず理事者より、資料に基づき、未来のつくり手として必要な資質や能力を着実に身につけられるよう取り組まれている、区のプログラミング教育やグローバル人材の育成についてご説明をいただき、その後、ご質疑、ご意見等をお願いしたいと思います。\nそれでは、本件につきまして、理事者より説明をお願いいたします。"},{"i":135,"speaker":"熊谷指導課長","text":"それでは、所管事務調査、次世代教育についてを説明いたします。まず、資料１「グローバル人材の育成に向けて」をご覧ください。\nグローバル人材が現在、求められる背景ですけれども、１つは、東京２０２０大会を契機に、外国人とのコミュニケーションの機会が増加していること。２つ目として、社会・経済・政治をはじめ、あらゆる分野・場面でグローバル化が進展していること。そして３つ目として、企業等さまざまな組織において、ダイバーシティ、いわゆる多様化が促進していることが挙げられると思います。その一方で、海外留学や海外赴任を敬遠するなどの、日本の若者の内向き志向があるといったことも挙げられるかと思います。\nそうした背景を踏まえて、目指す人間像ですが、多様な人々と協働しながら、困難に負けず生き抜く力を持つ人。日本の未来を担い、社会の一員として、その発展に貢献する人。伝統と文化を尊重するとともに国際的な視野を持つ人が挙げられます。これらは、品川区立学校教育要領の重点を踏まえたものでございます。\nこうした人材を育てるために、育成すべき資質・能力と態度としまして、使える英語力、積極的にコミュニケーションを図ろうとする態度、自国の文化への理解に基づく日本人としての自覚と誇り、豊かな国際感覚と多様性を受け入れる寛容性を掲げております。\nこうした資質・能力と態度を育てるために、本区では現在、大きく２つの事業を行っております。まず左側になりますが、品川英語力向上推進プランです。この事業の目的は、豊かな国際感覚を醸成するとともに、使える英語力を身につけ、積極的にコミュニケーションを図ろうとする態度を養うことであります。まず、指導体制でありますけれども、１年生から４年生は、楽しむ英語を目標に、週１コマ、年間ですと３５時間、１・２年生では担任とＡＬＴ。ＡＬＴは、いわゆる外国人英語講師でございますけれども、ＡＬＴとの授業。３・４年生では担任とＪＴＥ。ＪＴＥは日本人英語指導員ですが、この\nＪＴＥとの授業を行っております。５年生から９年生は使える英語を目指し、５・６年生では週１コマから２コマ、年間５０時間、担任とＪＴＥとの授業。７年生から９年生では週４コマ、年間１４０時間、授業を行いまして、うち担任とＡＬＴの授業は各クラス年間１０時間行っているところです。\n次に、ジュニア・イングリッシュキャンプです。楽しむ英語から使える英語への移行期に当たる４年生の時期に、ジュニア・イングリッシュキャンプを、自校の体育館、または今年９月に江東区の青海にオープンしましたＴＯＫＹＯ ＧＬＯＢＡＬ ＧＡＴＥＷＡＹで実施しております。\n次に、品川オンラインレッスンですけれども、これは、モデル校、ここに示しました６校の８年生を対象に、年間１０回、フィリピン在住の外国人講師と、インターネットを通じたマンツーマンの英会話レッスンを行っているものでございます。\nまた、９年間の英語学習の成果検証としまして、９年生に、聞く、読む、話す、書くの４技能テストを実施しております。今年度の結果なのですけれども、本区の９年生の約４６％が、ＣＥＦＲという、英語力を図る国際指標があるのですけれども、そのＣＥＦＲで、Ａ１レベルでした。これは日本の英検３級レベル、いわゆる初級レベルにあたります。\nそれで、教育課程外の取り組みなのでございますけれども、７年生から９年生を対象とした品川区グローバル人材育成塾がございます。これは、５会場、学校を５校使っているのですけれども、現在、２５０人の生徒が学んでいます。うち、希望者４０人が、福島県のブリティッシュ・ヒルズにおいて、夏季休業中に２泊３日の模擬留学体験を行っております。\n一方、右側をご覧ください。オリンピック・パラリンピック教育。これは、全校、そして幼稚園で実施しているものですけれども、世界ともだちプロジェクトと、日本の伝統・文化理解です。こちらはどちらも、グローバル人材育成を支える両輪の事業となっております。世界ともだちプロジェクトは、世界の多様性を知り、さまざまな価値観を尊重する態度を養うことを目標にしておりまして、それぞれの学校・幼稚園で、それぞれが選んだ学習・交流国５カ国についての調べ学習を行っています。また、調べ学習に加えて、学習・交流国の留学生や大使館職員との直接的・間接的な交流を行っています。間接的というのは、「実践例」の一番上に挙げましたけれども、品川学園において、イギリスの現地校との、スカイプを通じた生徒同士の交流を行っています。これが発端になりまして、先方の校長先生が日本にいらした際に、実際に品川学園で自分の学校の子どもたちとスカイプを通じてやりとりをしたということが今年度ございました。また、本区にある大使館、ここではインドネシア大使館を挙げてございますけれども、その大使館との関係から、インドネシア人学校の生徒との交流を行ったり、また本区にある大使館職員とのグローバル給食を実施したりというところでございます。さまざまな形で、各校・園で取り組んでいるところです。\n世界ともだちプロジェクトを行うためには、やはり日本の伝統・文化をしっかり理解していないと、浅い交流になってしまうということがあります。ですので、まず日本や東京、品川区の伝統・文化のすばらしさに気づき、それを理解し、理解するだけではなくて、それをほかの人に伝えようとする態度を養うことを目的に行っている事業でございます。茶道や華道、着つけなど、伝統文化の体験を行ったり、また地域の歴史・文化の学習を行ったりしています。市民科においては、全ての学校の３・４年生で茶道体験を実施しているところです。また、ここにありますように、本区にある喜多能楽堂での能体験・能鑑賞、また十二単の着つけ体験、また大森貝塚についての調査・研究・発表といったことも、日本伝統・文化理解の中で行っているところでございます。\n続けてプログラミング教育について、大関教育総合支援センター長が説明いたします。"},{"i":136,"speaker":"大関教育総合支援センター長","text":"２枚目の資料をご覧ください。プログラミング教育についてでございます。\n資料の左半分に、プログラミング教育についての考え方をまとめてございます。導入の経緯や社会的背景、位置づけ、そしてねらいまで、順を追ってご説明いたします。\nまず導入の経緯は、もう書いてあるとおりですので読み上げませんが、社会的背景といたしまして、現在の世の中、学校の生活、家庭の生活、さまざまなところで、パーソナルコンピューターを含めましたさまざまなコンピューターが日常生活の中に入ってきております。また、学習の場面でも、子どもたちは従前より、コンピューターを実際、手にして使っております。例えば、調べ学習をするだけでなく、発表をする際にはもう小学生の段階からパワーポイントを使って、自分の伝えたいことを入力して、それをもとに友達に発表する。そういう授業がもう数年前より、さまざまな小学校で当たり前のように見られる時代になってきております。このような社会的背景の中で、やはりあらゆる活動の中でそのコンピューターを適切に活用できる。そこが重要だという時代となってきております。コンピューター自体を理解するだけでなく、上手に活用していく力を身につけることが、将来どのような職業につくとしても、もう必ず極めて重要だということで、文部科学省の手引でもうたっているような内容でございます。\nそれを受けまして、学習指導要領の中では、児童がプログラミングを体験しながら、コンピューターに意図した処理を行わせるために必要な論理的思考力を身につけるための学習活動というものを位置づけるようになりました。従前より、もう既にコンピューターを扱っていると申し上げましたが、例えばデスクトップ型のパソコンを、グループ何人かで１台使って、グループの考えたことをパワーポイントに落とし込んで、クラスのほかのグループの子どもに発表する。そんな場面が、小学校５年生や６年生あたりだと、さまざまな学校で、普段の日常の生活の中で入ってきております。それは、いろいろな教科の中で実際に行われております。社会科で調べたことであったり、あるいは理科で調べたことなどを友達に発表する。そしてまた、その発表の方法として、１つの道具としてのコンピューターをどのように扱っていくか。そういった部分の中に、本人が意図せずとも、パソコンに論理的に命令、プログラミングをし、入力することによって、意図した動き、例えば文字がここで大きく拡大する、色が変わる、フラッシュをさせて目立つようにする。さまざまな操作が発表の中では出てまいります。\n１つの例を今挙げましたが、そのような発表する活動を通し、プログラミング的思考と文部科学省では捉えておりますが、子どもたちは、何か意図した一連の活動というものを行う際に、既にわかっている知識や技術を活用して、実際に文字を大きくしたい、フラッシュさせたい、色を変えたい、そういった動きを命令する。プログラミングをして、実際に思ったとおりに動くのか。命令が間違っていれば、意図した動きと違う動きをコンピューターはします。そういった試行錯誤をすることによって、自分の意図した結果に導いていく。問題を解決していく。そういった一連の作業をプログラミング的思考と捉えております。\nしたがいまして、左の一番下の段に４点示してございますが、プログラミング教育のねらいといたしまして、プログラミング的思考を育むこと。２点目は、プログラムの働きやよさ、情報社会がコンピューター等の情報技術によって支えられていることに気づく。３点目が、コンピューター等を活用して身近な問題を解決したり、よりよい社会を築いたりしようとする態度を育む。そして４点目ですが、各教科等での学びをより確実なものとする。この各教科等での学びというところ、もう既に従前よりプログラミング教育としての内容を、各学校が取り入れてきていると申しました内容が、まさにここにあらわれている部分でして、さまざまな教科の学習の中でプログラミングをして、友達に発表する、機械を動かすという活動の中で、その教科の学習のねらいを、自分がもう一度しっかりと深く学び取っていくというねらいが実現できます。\nそれでは、区立学校における具体的な実践の例を右側のほうに載せてございますのでご紹介いたします。右側、上の欄は京陽小学校の実践例でございます。京陽小学校は平成２８年度に、東京都教育委員会の言語能力向上拠点校の指定を受けまして、当時、「デジタルテクノロジーの書き手を育てる～プログラミングを用いた課題解決学習～」という研究を推進いたしました。６年生が、市民科において１年生のためにゲームのプログラミングを考えて、実際にそのプログラミングを入力して、思ったとおりにコンピューターが動くのかどうか。そういったことを体験しながらプログラミングにまずは触れてみるというような研究に取りかかり、区内で意図的にプログラミングという定義をとったものが、この平成２８年度の内容です。さらに、同じような写真がこの枠にはございますが、例えば４年生の理科においては、プログラミングソフトのスクラッチを活用しまして、理科の学習の中で、子どもたちが生き物図鑑づくりを実践いたしました。植物や昆虫の写真などをコンピューターに取り込むと同時に、解説を自分たちでどうやって表示するか、友達にどこをどう印象づけて伝えたいのか、文字をどんなふうにあらわせるのか。いろいろ子どもたちが自分たちで考えて、自分なりの考えをプログラミングすることで、その行為を通して、昆虫ですとか生き物のありさまというものを深く学び取ることができたと、この当時の成果発表を受けております。\n下の段には、第二延山小学校の実践例をご紹介してございます。平成２９年度、昨年でございますが、教育総合支援センターのモデル授業といたしまして、ＩＴ企業と連携した、「プログラミングを体験しながら、『ペッパー』を動かしてみよう！」という単元を、５年生の市民科で実施しました。単発の授業でございましたが、ペッパーにどのように子どもたちが読み聞かせ活動をさせるかという取り組みでございました。グループでいろいろ話し合う中で、ここでペッパーに両手を挙げさせよう。万歳をさせた中で読み聞かせをさせようとか、あるいは大きな声を出させようとか、いろいろなアイデアを出しながら、試行錯誤してプログラミングしている様子を私も見てまいりました。\nそういった取り組みが各校に今、広がりつつあります。平成３０年度、今年度でございますが、東京都のプログラミング教育推進校の２年間の指定を、延山小学校と第二延山小学校の２校が受けております。さらには、それ以外に、品川ルネサンス推進事業といたしまして、希望のあった小学校、延山小学校、第二延山小学校以外にも、御殿山小学校、旗台小学校、上神明小学校、鮫浜小学校で行い、内容はそれぞれの学校が自由に選択していただいております。先ほどのペッパーを使った内容以外に、スクラッチを使う学校もございますし、あるいは、ＰＥＴＳという、ブロックを組み立てる小さなロボットを使い、指示のとおりに右に曲がったり真っすぐ進んだり、地図の上をゴールを目指して動かす、そのためには、どういうふうにプログラミングをすればいいのかということで、どちらかというと低学年向けに、推進校以外の学校も、従前から一部の学校では取り組んでいる内容ではございますが、新たに導入するに当たって機材を購入したりするなどの支援を行っております。なお、最初に紹介しました京陽小学校などは、推進校に入ってございませんが、日常的に継続してスクラッチを取り入れたりなど、プログラミング教育を日々のさまざまな学習の中で取り入れつつございますので、区全体といたしましては、今、さまざまな学校がいろいろな教科で、どんな場面でプログラミングができるのかと試行錯誤しております。今年度、そして次年度、２年間かけてさまざまな取り組みを広げ、区内の各学校で情報を共有し、平成３２年度からの完全実施に向けて備えているところでございます。"},{"i":137,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑、ご意見がございましたら、ご発言願います。"},{"i":138,"speaker":"鈴木（博）副委員長","text":"最初の指導課長から説明があった品川英語力向上推進プランのほうなのですが、ＡＬＴとＪＴＥと書いてあるのですが、これは何の略なのでしょうか。\nそれと、あと二点。もう一つは、日本の伝統・文化理解を学ぶということは、オリンピック・パラリンピック教育の上で、非常に大切な、非常にすばらしい試みだと思うのです。また世界ともだちプロジェクトも非常に必要なことで、いろんな国の言葉を学ぶということも大事だと思うのですが、日本の伝統・文化理解と英語教育というのを合体させて、日本の文化を英語で表現するなどというような授業というのは考えられていないのでしょうか。\nそれと、あともう一点は、これは、「タイ、ザンビア、セルビア、ブラジル大使館職員とのグローバル給食を実施」と書いてあって、なぜか下の写真はモルディブになっているのですけれども、例えばセルビアとかザンビアというのは、郷土料理みたいなのがあるのかという気もするのですが、例えば食物アレルギーの関係などで、あまり現地のものを食べると、何が入っているかわからないです。以前、東京都のほうで、食物アレルギーで亡くなった子どもがいるのですけども、あれはチヂミを食べて、誰もおかわりをしなかったので、率先して手を挙げておかわりしたら、おかわりしたために食物アレルギーを起こしてしまったのです。だから、食べなれていないものとか、何が入っているかわからないものに関しては、食物アレルギーに関して何が起こるかわからないという点も考慮されているのでしょうか。その２点をお伺いします。"},{"i":139,"speaker":"熊谷指導課長","text":"まず２点目のご質問でしたが、英語で日本の文化を紹介するということは、発達の段階にもよりますけれども、検討しております。例えば、地域の方を講師とする品川宿めぐりを城南小学校が行っているのですけれども、学んだ後、それを、できるだけ知っている英語を使って外国の方に紹介し、おもてなしをしようというところまで、学習としてつなげております。また、実際に十二単の着つけ体験等も行っているのですけれども、着て終わりではなくて、それを英語でどういうふうに説明すると理解していただけるのかというようなことについても、英語の時間を使って学習に取り組んでいると聞いております。"},{"i":140,"speaker":"篠田学務課長","text":"グローバル給食のアレルギーに関するご質問でございます。グローバル給食につきましては、実施に当たりまして事前にさまざまな形で勉強会等を開いています。１つは、大使館の方々に、学校に行っていただいて給食を体験していただいたりということもありますけれども、あわせまして、どんな現地の料理があるかということで、こちらも勉強会をします。そのときに、さまざま食材等についても勉強しています。それで、物によってアレルギーのものが当然ございますので、実際に現地で料理をつくるときの食材はどんなものが必要で、どんなアレルギーがあるのかなど十分確認した上で、必要であれば当然、グローバル給食を食する子どもの中には、こういったアレルギー対応が必要な子どももいるので、そういった場合には当然、除去食として対応できるような形で考えていくというふうな対応をとっているところでございます。"},{"i":141,"speaker":"熊谷指導課長","text":"一番最初のご質問でございますけれども、ＡＬＴについては、Assistant Language Teacherの略でございます。そして２点目のＪＴＥ、日本人英語専科指導員でございますが、これはJapanese Teacher of Englishということで、その略でございます。"},{"i":142,"speaker":"鈴木（博）副委員長","text":"常日ごろ略語を使っていると、もとの言葉がわからないことがあるので、文書の最初には正式な表記を入れていただけると非常にありがたいです。"},{"i":143,"speaker":"熊谷指導課長","text":"はい。"},{"i":144,"speaker":"鈴木（博）副委員長","text":"それと、あと食物アレルギーなのですけれど、食物アレルギーの研究をするのではなくて、外国で使う食材にどういうものが入っているかを調べてほしいのです。例えば小麦アレルギーがあるのだったら、小麦アレルギーがある子どもはアレルギーを除去しなければいけないので。それで、除去する場合は、では除去してどうするのかとか、当然そういうことを考えなければいけません。要するに、一般論ではなくて具体的に、重大アレルゲンというのがあるので。アレルギーの原因、何が入っているかということをちゃんと調べて、その上でやらないと、せっかく有効な食事をして、非常にまずいことが起きてしまったら困るのです。ですから、その辺はしっかりと対応をよろしくお願いします。要望ということでお願いします。"},{"i":145,"speaker":"塚本委員長","text":"ほかに。"},{"i":146,"speaker":"南委員","text":"グローバル人材のほうの背景の４点目に、「海外留学や海外赴任を敬遠するなどの、日本の若者の内向き志向」と書いてあって、これは本当に英語教育を、また国際社会化がどんどん進んでいく中で、こういう現象があるということは事実なのかなと思って、何が原因でこんなふうになっているのだろうと、すごく気になるところなので、どういうふうに捉えているか教えていただければと思います。"},{"i":147,"speaker":"熊谷指導課長","text":"こちらにつきましては、文部科学省も、それから経済産業省も、東京都教育委員会も、非常に課題として挙げているところでございます。高校生が外に出ていかない、留学をしたがらない。その理由なのですけれども、幾つか背景はあるかと思うのですけれども、やはり日本の環境、落ち着いた安定した環境の中から出ていこうとしない。楽なところを選んでしまう。あえて、挑戦していこうというチャレンジ精神といったものが、なかなか育っていない若者が多いのではないかというところが１つの要因ではないかと思われます。"},{"i":148,"speaker":"南委員","text":"なるほど。そういうところもあるのかと思ったのですけども、でも、わりと、小学校の時代からいろんなことにチャレンジしようという、意識的なそういう教育的指導はずっとしていると思うのです。そのわりには、文部科学省も経済産業省も指摘してしまうような全体的な傾向があると。その因果関係というか、その辺はどういうふうになっているのかと、すごく思いますし、特に、島国という表現がいいかどうかは別としても、そういう地理的な条件がある日本だけに、やはり外国に行って、外をいっぱい見てこようということは、本当に大事なのではないかと思うのです。私の勝手な想像で恐縮なのですけれども、出ていくというか、何か新しいことに挑戦するのに非常に臆病になっているというか、自己肯定ができないみたいな傾向があるのではないかと思います。そうであるとしたら本当に残念なので、教育の方向性とか教育そのものを、やはり一定程度、振り返っていく必要があるのかなと。自己肯定ができるような教育を重視していく必要があるのではないかと思ったりしているのですけれども。果たしてそれがいいかどうか、適切、言い得ているかどうかは別としても、教育委員会としてはどういうふうに見ているのかを教えていただければと思います。"},{"i":149,"speaker":"熊谷指導課長","text":"平成３０年１月末から２月にとりました児童・生徒アンケートですけれども、英語の学習は大切だと思っている品川区の子どもたちは、２年生から９年生まで９０.８％いるのですけれども、ただ、実際、将来、外国へ留学したり国際的な仕事につきたいと思うかと聞くと、なかなかそれが厳しい状況で、半数ぐらい、４５.６％というところがあります。ただ、９年生になると自分の将来が見えてくるというところもあって、５割程度、４７.６％の子どもが、将来、外国に留学してみたいと答えていますので、時期もあるかと思うのですけれども、やはり怖がらずに自分の力を試していこうという、そういった底力を子どもたちにつけていくことが大事ではないかとは考えます。"},{"i":150,"speaker":"南委員","text":"そうですね。一人ひとりの、やはり子どもですから、当然、自分の力などというのは、自分で見定める能力など到底ないわけですけれども、やりたいという意欲だけは本当にいっぱい出てくると思うので、伸びていくというか、「あなたの存在自体が大事よ」ということも含めて、やはり一人ひとりの個の状況を認めながら、発展していけるような指導、やっていただいているとは思うのですけれども、そこを本当に重要に考えているので、改めてそういう方向性もお願いしておきたいと思います。"},{"i":151,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":152,"speaker":"飯沼委員","text":"グローバル人材のところの英語力の向上のところなのですけれども、先日、地域の小学校公開授業に行ったのですが、１年生と２年生、ＡＬＴの元気な先生のもとで、すごく活発なやりとりをやっていました。ここに書かれている楽しむ英語という中身、一緒にゲームをするとか、カードで発音をみんなでやりとりするとかというところを見せていただいたのですが、内容を教えていただきたいのと、ＡＬＴやＪＴＥの先生はすごく担任の先生にとって頼りになるというか、力強い立場にいらっしゃると思うのですが、どうやって探していらっしゃるのか、どこから来ているのかというのを教えてください。"},{"i":153,"speaker":"熊谷指導課長","text":"ＡＬＴと一緒の授業ということで、１・２年生の授業をご覧になったと思うのですけれども、ゲームをやったり、それから歌を歌ったりというところからスタートいたします。まず１・２年生について、ＪＴＥではなくてＡＬＴをお願いしている理由は、世界にはいろんな国の方がいて、白人の方も黒人の方も、アジア系の方もさまざまな人がいて、さまざまな文化があるのだということを、１・２年では学ばせたいということで、ＡＬＴをティーチングの相手としてお願いしているところでございます。\nそれからＡＬＴなのですけれども、こちらについては、事業者に一括で委託しているところです。ただ、ＪＴＥにつきましては、非常勤講師として直接、指導課が雇用しております。これは非常に人気がありまして、私どもが面接を行って採用しているところでございます。"},{"i":154,"speaker":"飯沼委員","text":"ＡＬＴのさまざまな人種ということで、私が伺ったときは東南アジアの方だったのです。ちょっと皮膚の色も日本人に近い方でした。そういった意図があって、いろいろな方を採用されているということなのですね。わかりました。\nあと、オリンピック・パラリンピックの教育やプログラミング教育は、どういう授業というか時間帯、市民科もかなり入っていますが、どういう時間を使ってこういうものを取り入れているのか教えてください。"},{"i":155,"speaker":"熊谷指導課長","text":"まず、オリンピック・パラリンピック教育ですが、全ての教科の中で行っています。そのためにやるというよりは、例えば市民科でこれまで行ってきた授業と関連づけて行ったり、また保健体育等もそうですけれども、品川区で言うと、品川区立学校教育要領に準じて、その内容と関連づけて行ってきております。"},{"i":156,"speaker":"大関教育総合支援センター長","text":"プログラミング教育におきましても、さまざまな教科の中で扱う場面がございます。先ほどもご紹介しましたように、理科の発表で使う場面もあれば、あるいは市民科の中でステップ５として、自分の取り組んだ内容を発表したり、友達の発表を聞いたり、そういった場面で使うような場合もございます。"},{"i":157,"speaker":"飯沼委員","text":"結構、プログラミングのところは、いろんな授業の展開があるのかと思うのと、今、学びの素材が本当にいろいろ多様化して、私たちの育った環境と違うので、やはりある意味では学校で誰もが触れられるというのはとても大事かと思いますけれども、苦手な子もいるのでしょうか。みんな、ついていけているのでしょうか。"},{"i":158,"speaker":"大関教育総合支援センター長","text":"今の小学生を見ますと、もう生まれたときから親御さんがスマートフォンなどを使っているのをそばで見て、ゲームあるいは見たいテレビ番組を録画する操作を、意図的に、無意識の段階からやっていて、とても私たち大人よりも子どものほうがうまいというのが正直なところです。\nまた、品川区の区立学校はＩＣＴ環境が早い段階から整ってきておりますので、多分、他区に比べても、比較的いろいろな場面で、教員も使いますし、子どもたちもグループで実際に触れるという場面はとても多いと感じているところでございます。"},{"i":159,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":160,"speaker":"つる委員","text":"両面にわたるのですけれども、次世代教育だけでなくてそもそも論なのですけれど、学校の公教育の中の授業でいろんな教科がある中で、その教科や授業を行う目的観みたいなものというのを最初にきちっと理解していることが、学習意欲の向上にすごく大きいと思うのです。これはいわゆる日常の授業で実践されていることだと思うのですが、特に英語などについては、最初に、どういう目的観、これをやるのだという意味みたいなところを児童・生徒に伝えているのかとか、あとは、その取り組みの一番最初だけではなくて、都度都度、授業の中でどういうふうに教員の方が上手に工夫して伝えているのかというのを、まず教えてください。"},{"i":161,"speaker":"熊谷指導課長","text":"今ご指摘のありましたとおり、全ての授業に共通するのですけれども、この授業が一体どんな目的で行われているのか。今日はどんな力をつけたいのか。それをしっかり伝えた上で行っていくことが重要だと思っています。特に７年生から９年生に関しては、きちんとそれを明確に示していくということをしないと、ただ繰り返し、繰り返しの英語の授業になってしまうという危険性もありますので、それはしっかり板書をするように教員には伝えているところです。また、１年生から７年生に関してなのですけれども、ＪＴＥも必ず今日の目的ということは最初に伝えるようにしているのですが、なかなか１・２年生のＡＬＴとの授業のときには、担任が伝えそびれてしまうということもありますので、そういったことも含めて指導を行っていきたいと思います。"},{"i":162,"speaker":"つる委員","text":"ＡＬＴの方などは、特に１年生・２年生などは、逆にそれ自体がもう目的みたいな部分にもなるのかなどと思うのです。いろんな、国際結婚されている方などもいらっしゃると思うのですが、特に日本はまだ、日常生活の中で外国の方が行き交うということは、なかなか少ない中で、先ほどの、飯沼委員からあった、いろんな国の方と接する機会という意味では、それ自体が、ああ、こういう外国の方とお話しするときの道具なのだなというところで、きっかけにはなるのかと思うのです。やはり全ての教育においてもそうなのですけれど、それを何で学ぶのか、常に意識を持っていただかないと、上滑りだけ、テクニカルな部分だけで、よく言われる受験英語だとか、そういった部分になっても、意味がないということで、まさに楽しむところから入っていただいて、使えるものになっていく、消化させていくというところなのです。それを、こういう紙で出していただくと、背景、人材像、資質等々と体系的にわかるのですけれども、実際にやってもらっている児童・生徒がそれをしっかり意識して取り組んでいけるようなモチベーションを維持していただくということが、せっかくいろいろやっていただいている中ですごく大事かと思ったのです。\nあと、早速、ＴＯＫＹＯ ＧＬＯＢＡＬ ＧＡＴＥＷＡＹを活用されていて、すごいと思ったのです。これは、決算特別委員会などで活用をどういうふうにしていくのかと伺おうと思ったら、もう既にやられているということで、これは一般利用もある中で、学校が積極的にというところだと思うのですが、非常にいい機会だと思いました。なので、私も品川区の公教育を受けて、当時の英語を学ばせていただいて、今、自身の英語力というのを毎回、いろんな委員会で言うのですけど、自分の能力なのです。教育委員会や学校にだけ責任を持てとは言えないですけれども。せっかく今、これだけ力を入れてもらっている児童・生徒が、本当にいろんなキャリア教育などにもつながっていくのでしょうけれども、常にそうしたところも意識させながら、楽しむ英語、その先を意識させながら使える英語ということでやっていくと、すごく努力だとか、自分で加えていこうというふうになっていくのではないかと思うので、そういったところの工夫が知りたいです。これは通常の学校教育のことだと思うのですが、ぜひお願いしたいと思います。\nあと、オリンピック・パラリンピック教育で、伝統のところなのですが、ここで実践例で挙げていただいているのは、どちらかというと幅広い、大森貝塚などは歴史的な、かなり古代の感じになっているのであれですけれども、品川区の伝統というのはいろんなものがあると思うのです。主だったもので結構なので、いわゆる品川区の伝統として児童・生徒が学んでいるものというのはどのようなものがあるのか教えてください。"},{"i":163,"speaker":"大関教育総合支援センター長","text":"まさにさまざまな地域ごとに品川区ならではの文化と伝統があると考えまして、実際、本年度より各学校では、地域の方を招いて地域の文化と伝統について教えていただくなどというところも取り組みを始めたところです。また、あと小学生段階ですと、「わたしたちの品川区」という中で、それぞれの地域には歴史的な遺物、どのようなものがあるかなどというものも副読本として学んでいるところでございます。"},{"i":164,"speaker":"つる委員","text":"具体的な内容が欲しかったのですけれど、今のは多分、歴史みたいなイメージで私は理解したのですが、品川区の各地域でいわゆる伝統と言われているもの、どういったものを皆さんに伝えていただいているのかというのを教えてください。"},{"i":165,"speaker":"大関教育総合支援センター長","text":"歴史以外に、例えば地域の、もうそれこそ品川甚句や品川音頭といったものも１つの伝統だということで、連合体育大会で子どもたち全員で踊ったりというような取り組みもしております。また、今、お求めいただいているのが、歴史あるいは、文化的なこと以外ということで、地域によってはもしかすると、地域ならではの伝統料理、例えば品川カブを使った料理などもあるのかもしれません。そのほか、いろいろあろうかと思いますが、今すぐに浮かばず申しわけありません。"},{"i":166,"speaker":"熊谷指導課長","text":"オリンピック・パラリンピック教育の中で、子どもたちに「ようい、ドン！しながわ」という教材を渡しているのですが、例えば、江戸時代、御殿山の桜が非常に有名な名所だったというところで、御殿山の桜であったり、あとは食べ物として、ノリを使っているので品川巻き、それを英語で伝えるというようなことも、おもてなしの一つとしてオリンピック・パラリンピック教育で行っています。\nまた、あとは遊船であったり、釣りざおであったり、そういったこともオリンピック・パラリンピック教育の一環として、まず品川区を知るというところで掲載しているところでございます。"},{"i":167,"speaker":"つる委員","text":"伝統と言うと、品川区であれば、いつも毎年、１年に１回やっている「技と味」とか、あるいは伝統工芸などが、ぱっとイメージとして湧くのですが、例えば、今言っていただいた古墳もそうですけれど、歴史、御殿山の桜なども、その場所として、地域の人がどういうふうにして、まさにそれを伝えていかれて、慣習ないし習慣の中でどうされているかというのが、やはり伝統だと思うのです。そういったところの大切さということも、地域に対する誇りなどということになっていくのかと思うので、またぜひ別の機会で品川区の伝統を、ちょっと具体的にいろいろ伺えればと思ったので、また改めてこれについてお聞きしたいと思います。\n基本的にプログラミングのほうで、英語もそうなのですけれど、これからまさに進み始めたというところなので、なかなかいろんな効果とか成果というのがその先になっていくわけですけれど、国のほうでもそういう会議の中で必要性というのはまとめられて、モデル実践などとなってきているわけですが、逆に、これはあくまでも、それを活用してのプログラミング的思考なのですが、ただ、実際のリアルな生活の中で、人と人とのかかわりの中での、いわゆる１つの指示ないし命令とか言葉を交わしたことで出てくる答えというのが必ずしも同じではないわけですよね。そうすると、こうすればこういう答えがプログラミング上は論理的には出てくるのに、そういう答えが出てこない。人と人との中では出てこないということを、逆にどうつかませていくのかというきっかけにしていかなければいけないのかなと思うのです。だから、社会の１つのツールとか今後のテクノロジーとか、そういうところでの必要性と、一方でそういう目の前にあるリアルな生活の中での、日常の中での反応というのは、当然、違う反応なわけです。０・１・０・１などという、いろんなプログラミングを自分の中でやりとりして、人と接したときに違う答え、違う反応が出てきたということに対する対応力などというものについては、どういうふうにしてやっていくのかということを含めて、その先、どういう形で検証等をしていくのか、その辺を教えてください。"},{"i":168,"speaker":"大関教育総合支援センター長","text":"今ご指摘いただいたとおり、まさにコンピューターを動かした反応と、実際の人間同士の反応で違う場面があったり、そこで戸惑うこともあるかもしれません。例えばプログラミングを取り入れた授業をやってみたけれども、かえってここは無理にコンピューターを導入するより、それこそ手書きのものを使って伝えてみたり、手書きのものを活用することで、ねらいをより達成できたのではないかなどという意見が、授業の後の教員同士の反省で出てくるなどという場面も私は見てまいりました。実際にそういった対応力というところと、プログラミングをしてコンピューターが上手に操作できるということとは、また別の課題があるのかもしれません。そこも今、現場としては、さまざま試行錯誤する中で、どんな場面、どんな教科、どんな単元、どんなねらいに、コンピューターが適している、使える授業があった。あるいは逆に、それよりはコンピューターに頼らないほうがかえってねらいは達成しやすかった。そのような意見も踏まえて、それぞれの各校の取り組みを今後、情報共有して、取りまとめてまいりたいと考えております。"},{"i":169,"speaker":"つる委員","text":"どこかの報道ベース、ニュースで見たら、保育所の入所の選考をＡＩにしたら、人間が選別するのとほぼ変わらなかった、ニアリーイコールだったというのがあって、活用によっては、すごくおもしろいと思ったのですが、やはり、今ご答弁いただいたとおり、今後それをどういうふうに成果として見ていくかなどということもしっかり見ていただきながら、先ほど申しあげた、人間の心というのはプログラムしてやれるものではないわけですよね。そこがまさにＡＩとの違いだと思うので、そこを本当に意識しながら、活かすものはしっかり活かしていきながら、本来の趣旨といいますか目的感をしっかり達成しつつ、そういったところにもきちっと対応した活かし方をやっていただきたいと思います。"},{"i":170,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":171,"speaker":"石田（し）委員","text":"まず、品川区の英語教育、いわゆる小学校１年生から英語教育を始めて、今の９年生は、１年生から英語教育をもうスタートしているのですよね。その方たちと、今までの、中学校での英語だけを習った人たちとの違いというのが、今の７年生から９年生にどのように出てきているのかという分析をされているのかどうか。また、されているのであれば、今、どのような評価がされているのかというのを教えていただきたいのと、ここでも出ている、いわゆる使える英語力というのはどのようなことを指しているのか、改めてお聞かせいただきたいと思います。\nそれと、これは全体、両方とも、プログラミングも英語教育もオリンピック・パラリンピック教育もそうなのですけれど、今、学校でさまざまな、いわゆる教科以外の部分でいろいろ教えていただいていて、専門的なものが非常に多くなってきていますよね。それで、例えば先ほどのＡＬＴ、ＪＴＥ、\nＡＬＴは委託されていて、ＪＴＥは教育委員会などで選定されてということでしたが、そういった専門的な講師をお呼びするとき、例えば地域の方ももちろんいたりしますよね。地域の方に学ぶ授業のような、学校で行うのか分かりませんが。それで、プログラミングのところにも、ＩＴ企業との連携と、第二延山小学校のところに書いてあるのですけれども、そういった専門的な講師をお呼びするときというのは、教育委員会主導なのか学校主導なのか、もちろん物によって全然違うのだとは思うのですけれども、どういったマニュアルというか方針みたいなものがあるのか教えてください。"},{"i":172,"speaker":"熊谷指導課長","text":"まず、これまで平成１８年度から１年生から英語教育を行ってきたわけなのですけれども、その結果と申しましては、まず、これは昨年度の、ちょうど平成２９年１２月１日のデータで、国で調査したものですが、英検３級以上を取得している生徒が国では２２％。これは７・８・９年生です。ところが東京都は３３％。それに対して品川区の７年生から９年生は４４.５％ということで、東京都よりも１０％以上、国よりは２２％以上、上回っているというのが１つ大きな成果になっていると思います。それから、先ほどお伝えした４技能のテストの中で９年生で実施したスピーキングなのですけれども、６５％以上の子どもがいわゆる英検３級以上ということで、これは全国的にもなかなか、９年生の段階で、ここまでスピーキングが身についている子どもたちは少ないということで、実際に４技能テストを行っている事業者からも、珍しい状況ですとお声をいただいているところです。それから、品川区の学力定着度調査においても、全ての学校で英語の平均が全国よりも上回っているということで、これも大きな成果ではないかと思っています。\n２つ目のご質問なのですけれども、使える英語は非常に難しいです。一言で、使える英語はこれですとは、言いづらいのですけれども、ただ１つは、先ほどの４技能、聞く、読む、話す、書くが総合的に身についているということもあるかと思うのですが、それだけだと使える英語だとは思っていません。英語がしゃべれる、英語が読める、書けるだけでは、やはり英語として語学として本来の意味をなさないとするならば、やはり使える英語というのは豊かな心の部分、文化をしっかり持っている。そういったものも踏まえた上で、しっかり自分のことを自分の言葉で伝えていける。そういったものが使える英語ではないかと捉えております。"},{"i":173,"speaker":"大関教育総合支援センター長","text":"外部講師選定に当たっての１つの目安、基準という部分でございますが、まず学校と教育委員会が十分に相談しながら選定に当たるというのは前提となります。そのほか、例えばプログラミング関係ですと、もう東京都教育委員会がプログラミング教育推進の教育会を設けておりまして、そこに加入していただいている企業というのが１つの目安になっております。また、そういったこと以外の場面で何か新たな講師をお願いしなければならない、例えば租税に関する内容で税理士会にお願いするなどという場合は、当然、地元の地域の税理士会に情報をいただくなど、そこは教育委員会として学校と一緒に相談しながら、心配のない講師というものをお願いします。また、新たにお願いする際には事前に十分、情報共有をして、どういう目的でどういうことをお願いしたいというのもお願いした上で、外部講師をお願いしているところであります。"},{"i":174,"speaker":"熊谷指導課長","text":"オリンピック・パラリンピック教育につきましては、本区開催・応援競技の３競技については、私ども指導課でご紹介して、そして予算もつけているところでございます。また、それ以外のオリンピアン・パラリンピアンを招致したいときには、都からも紹介がありますし、また私どものほうでも紹介している経緯もあります。また、各学校がコミュニティ・スクールのコーディネーターを通じて、そのつながりで呼んでくるということもあります。また、都のほうでそうした講師を紹介するホームページもありますので、そこから調べてお呼びするといったこともございます。ですので、さまざま、そういった状況でございます。"},{"i":175,"speaker":"石田（し）委員","text":"品川区の子どもたちの英語力が非常に高いというようなご答弁で、わかったのですが、私が聞きたいのは、要は、今まで、それこそ我々世代もそうですけれども、中学校からの英語教育だったわけです。その子どもたちと、私世代はもう全然調査できないでしょうけれど、いわゆるぎりぎりのところの子どもがいますよね。小学校１年生から、いわゆる小学校から英語を学んだ子どもと、中学校から学んだ子どもというのがいて、そこまで英語の授業内容、今、いろいろやっているのはわかっているのですけれども、根本というか、教科書ベースでいったときに、大きくそこまで変わっていないのであれば、その子どもたちの、同じ、例えば９年生なら９年生、７年生なら７年生でいいのですけれども、どのように変化があるのか。いわゆる前の世代の子どもの英語のテストなどのものと、今の子どもたちのテストの結果などがどうなっているのかという調査をされているのか、されているのであれば、何か変化はあるのか教えていただきたいと思います。\n使える英語の部分も、本当に模範解答が返ってきましたけれども、日本の今までの英語教育というのは、読む、書くだったんです。それはなぜかというと、例えを言うと、「This is a pen.」などというのも典型的で、あれはもう文法ありきで、ふだん、「これはペンです」とは言わないですよね。私は、使える英語というのは、根本部分がまさにそこにあるのではないかと思います。それで、「これはペンです」という、なかなかふだん使わないものを一生懸命教えているのは、何故かといったら、文法があっての基礎の部分を教えるから、「This is a pen.」というのが出てきたのでしょう。そうではなくて、もう少し、それこそスピーキングの部分なのか、リスニングの部分なのか、やはりそういったところを重視していくというのが、多分これからの英語、いわゆる使える英語という部分になるのかと思います。\nそこで、今、ほかの自治体でも導入し出している、ＡＩ機能があるロボット、Ｍｕｓｉｏという、ロボットでＡＩの機能が搭載されていて、英語の発音だったり、復習などの教材に使えるロボットのようなものがあるのですけども、それを例えば学校などに導入していて、子どもたちも対ロボットだから結構楽しくやっていたりするのです。そういった新しい技術もあって、もちろん人間が教えるというのはもう大前提なのですけども、別の部分、要は授業ではないところで、どうやってその子どもたちを教えていくかというところで、こういった新しい技術を活用したものというのは取り入れられるのではないかと思うのですけれども、そういった部分というのはどのように考えているのでしょうか。また、それと似たようなところで、英語教育も、小学生の特に低学年などというのは、多分、差が大きく出てしまうのではないかと思うのです。小さいときから親が熱心で、保育園なども英語がわりとプログラムが多いところに行かせていたら、１・２年生や３・４年生は結構レベルが、英語の場合は特にまちまちになってしまうのかと思うのだけど、そういった習熟度別の授業をされているとは思うのですけれど、こういう今回の次世代教育は、ほかの教科よりも大きく出てくるのかと思うのです。そういったときにどのように対応していくのか。それはさっき私が１つ言った、ＡＩの技術を使ったロボットもしかり、どういった習熟度別の、さらなる発展的な授業をしていくのか、今、現時点で何か、区としてやられているものがあれば教えていただきたいと思います。"},{"i":176,"speaker":"熊谷指導課長","text":"まず、９年間の英語教育を始める前と後とでどのように変容したかというところなのですけれども、実際のところは、そこまで資料としてデータが残ってはいないのですが、ただ、言えることは、ここ数年間、やはり英語の学力が上がってきているというところがあります。ということは、やはり１年生からやってきた積み重ねの部分、特に新カリキュラムになってからの英語力というのが非常に定着してきた成果ではないかと思っています。\n２つ目のご質問で、具体的に前段階の１年生から、特に３年生から６年生までのところで、子どもたちが文字と音の関係をしっかり系統的に学習していく。それで、それを早い段階から耳で聞いて、そして聞いたことを、ジェスチャーをつけながら、例えば『桃太郎』だったり『赤ずきん』だったりといったものを、手話を使いながら語っていく。そういったことを通して、リスニング力とスピーキング力が高まってきているのではないかと思います。そういった力が最終的に先ほどの、９年生になってスピーキング力が非常に伸びたというところにつながっているのではないかと思っています。ここで、やはり恥ずかしがり屋の子、そういった、自分を表現していくということが苦手な子もいるので、ちょっと英語が苦手という子も確かに出てくることもありますが、ただ、やはり英語だからこそ、そうした自己表現ができるという子もおりますので、そういった中で、英語の力をつけていきたいとは思っています。\nそこで課題となるのが、子どもたちが７年生になったとき、英語科は、都の教員が多く、他区から入ってきたときに、なかなか１年生から６年生まで身につけてきた土台があるということを理解しないで指導してしまうといった部分もありえるので、それを教育会で共有しているところですし、授業も行うというようなこともしています。また、今、指導課で作成しております、指導の手引といったようなものも、このリスニングの部分と、いわゆる音素と言っていますが、音をしっかり聞き取って話せるようにしていく、その部分も教員がしっかり指導を系統的に行えるように行っているところです。\nそうした中で、習熟度別といったご質問がございましたけれども、７・８・９年は習熟度別で、２学級３展開を中心に授業を行っています。やはり、どうしても苦手なところというのが出てきますので、そうした中で取り組んできているところですけれども、例えば先ほどお伝えした品川区グローバル人材育成塾で英会話のレッスンを行うということも、１つのそういった苦手部分を克服する、また得意部分を伸ばすというところでもありますし、あとは、品川地域未来塾等で行っていくということもあるかと思うのですが、プログラミング教育にもつながっていきますけれども、これからのＡＩといったところも勉強しながら、どういったことでつなげていくのが望ましいのか研究してまいりたいと思います。"},{"i":177,"speaker":"石田（し）委員","text":"初めの質問にもつながってくるのですが、いろいろな方が講師として来られる中で、一律に何かというのは難しいのかもしれないのですけれども、やはり学校というのはいろいろ複雑なものがあると思うのです。それで、例えば先生はわかっていても、外部の方から見たら、それが全然わからない。それで、例えば何かをしてトラブルになってしまうようなことというのが、せっかく教えに来てくれている人たちと、そういったものはできる限りないほうがいいのかなと思うので、その点というのは、基準ではないですけれども、ある程度の統一性を持った、いわゆる学校あるあるではないですけれど、例えば「こういったことには気をつけてください」といったものは、授業に関して一番知っているのはやはり担任の先生なのかなと思うので、ぜひその辺は一定の基準みたいなものを設けて、来られる方たちにも気持ちよく帰っていただけるような仕組みというのをつくっておいていただいたほうが、今後、多分、それこそコミュニティ・スクールもそうですけれど、いろんな方が学校に入ってくる中では、非常に大きな課題になってくるのかと思うので、その辺はぜひ教育委員会と学校サイドと連携していただいて、取り組んでいただければと思います。\nあと、ＡＩのロボット等もなのですけれど、楽しく学ぶと言うと、子どもたちはすっと入るので、飽きてしまうかもしれないけれども、１つのツールとして活用できるのであれば、特に英語の発音の部分などロボットは得意で、発音を学ぶというのは、実はあまり日本の担任の先生だと難しかったりするので、その点は、活用できるようなものにはぜひ常にアンテナを張っていただいて、いいものを導入していただければと思います。"},{"i":178,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":179,"speaker":"渡部委員","text":"英語をしゃべることもできる委員の質問の後で英語のことを話したくないのですけれども、グローバル人材育成塾はもう始まって大分、５年になるのですかね。それで、たしか最初、４校で４００人だか５００人だかでスタートしたように記憶しているのですけれども、今、５校でやっていて、７年生、８年生、大体どれぐらいの子どもたちが参加しているのかというのがまず１点。それと、何年かやってきて、何か変更点があったのかというところを教えてほしいのと、これは１年間を通してではないですか。わからないですけれども、途中で何回か出て、「もうやめた」となってしまう子どもがいるのか。あと、部活動などの配慮。例えばグローバル人材育成塾があるときは部活動はなしとか、何かそういう配慮があるのかどうなのか。それと、そこに参加している子どもが、イングリッシュキャンプということで、イングリッシュキャンプに行かれた方のお話を聞いたら、大分よかったとやはり言うんです。それで、実際どれぐらいの子どもたちが参加しているのか。逆に言うと、みんな希望者ということが書いてあるのですけれども、希望した子はみんな今まで行けているのか。抽選でふるいにかかるようなことがないのかというところをあわせて教えてください。"},{"i":180,"speaker":"熊谷指導課長","text":"グローバル人材育成塾ですけれども、平成２９年度ですが２４９人、そして今年度、平成３０年度は２５０人。これは偶然なのですけれども、ほぼ同じ人数でした。変更点なのですけれども、平成２６年度にスタートしたもので、後のご質問にもかかわってくるのですが、４月スタートにしてしまうと、部活動がどの程度あるのか、７年生がわからないということがあって、結局、ドロップアウトしていく人数が毎年２０人ぐらいいたのです。ですので、平成２９年度からはスタート時期を９月から翌年の７月までというふうに変更しまして、年間２５回にしました。そうすることで、部活動が大体このぐらいの回数で、そしてどの程度、出なくてはいけないかというのがしっかりわかってから入塾してくるということになりますので、そういう意味で、今はドロップアウトする子どもが非常に減っています。\nそれから、イングリッシュキャンプは大体４０人、平成２９年度も、そして平成３０年度も、４０人、引率しています。それで、希望は、大体いつも五、六十人は来るのですけれども、実は、このときだけ来たいという子どももいるのです。楽しいことだけはしたいのだけれども、普段のグローバル人材育成塾にはあまり出ていないといったこともありますので、８割は出ている子どもを連れていくというふうに、出席率で査定しております。そういった中で、大体４０人程度を引率しているところでございます。"},{"i":181,"speaker":"渡部委員","text":"人数で言うと当初から半分ぐらいに減ってしまったのかという気はするのですけれども、でも２５０人いて、希望が五、六十人、行っているのは４０人ということですけれど、あるということは、一定の成果が上がっているのだろうとは思います。先ほどの質問なり課長の答弁を聞いていると、英語教育がしっかり地について実績が上がっているというのは、聞いてわかるとおりですので、引き続きお願いしたいのです。\nそれで、これは少し横道にそれるかもしれないのですけれど、国際友好協会でリンフィールドカレッジがありますよね。せっかく、いいプログラムがあって、私も最近まで知らなかったのですけれど、学校長推薦枠というのがありますよね。これは、せっかくグローバル人材育成塾とかイングリッシュキャンプとかがあって、ここは何かリンクしていますか。そこに行っている子どもたちがある程度、優先なのだとか。私は優先するべきだという意味で、今、質問しようと思っているのですけれども、学校長推薦枠というのがあったので、この辺との接続というのは、思いついていなかったので、何か接続しているのであれば教えてください。"},{"i":182,"speaker":"熊谷指導課長","text":"委員ご指摘のとおり、毎年１名ずつ、各学校、校長推薦で行かせておりますが、直接的にグローバル人材育成塾に入っている子どもを優先ということにはなっていません。あくまでも校長推薦という形で行っているところです。"},{"i":183,"speaker":"渡部委員","text":"品川区が英語教育にすごく力を入れていて、仕組みも別でしょうし、所管も別なので、これは一様に言えないことですけれど、希望としては、せっかく今、品川区はこれだけのことをやってきているわけですから、例えば中学生が７年生の段階でグローバル人材育成塾というチラシか何かを見て、こういうのがあるのだと知ったときに、実はプログラムとして、オークランドの語学研修があるよ、一月ぐらい行けるよ、ここで一生懸命、積んできたら、こういうプログラムもあるよみたいなのが、私は一緒でいいのかなと思います。逆に、各校の校長が１名ずつ枠を持っているという意味がちょっとわからないし、向こうに聞いてみないとわからないので、向こうに聞いてみますけれども、逆にこういう英語教育の制度があってやっているのだったら、そこでその枠を持っている、教育長枠と言ったらおかしいですけれども、教育委員会のほうで、ある程度、枠を持っていて、そういう子どもたちを行かせてあげる。はっきり言いませんけれど、相当廉価ですから、そういうのもいいのかなと思って。これは答えは出ないでしょうから、意見として申し上げておきます。"},{"i":184,"speaker":"塚本委員長","text":"ほかにご発言はございますか。"},{"i":185,"speaker":"高橋（し）委員","text":"いろいろご説明をありがとうございました。その中で、内向きの志向などという話があって、それに関連して、先ほどほかの委員からありましたけれども、英語を勉強する目的というか目標というか。それで、英語に関する職業につきたいと思う子どもが少ないという話なのですけれど、やはり高校生に聞いても、英語を使ってどんな仕事につきたいかと聞くと、通訳とか、そういうものしか浮かばないわけです。それで、やはり英文科に行きたいのはなぜかという話をすると、そういうことになる、小学生などはもっとそうだと思うのです。それで、一般の企業に就職しても、英語を使ってたくさんの仕事をできるし、例えば市役所の中にも語学が得意な方がいらっしゃって、英語で仕事をしていますよね。そういう、英語を使って、そういった仕事の可能性が広がるというか、どんな仕事があるかというのを、やはり先生方で具体的に提示というか、キャリア教育と言うと大げさなのですけれど、「実はこんな仕事もあるんだよ」みたいなのをお話ししていただけると、すごく身近に感じて、英語を使っていこうと感じるところがあるのですが、その辺、なかなかキャリア教育をするのも難しいところがあるのですけれども、小学校でぜひそういった動機づけをしていっていただきたいという気がします。市民科の中の将来設計でしたっけ、その領域の、ちょっとそこまで時間的に厳しいかもしれないので、日常、担任の先生などが、そういったお仕事を提示していただけるといいのですが、英語というと、学校の英語の先生だったり通訳だったりＣＡだったり、そういうイメージしかないので、本当にいっぱいあるのだということを教えていっていただけるとありがたいのですが、そのあたりはいかがでしょうか。"},{"i":186,"speaker":"熊谷指導課長","text":"やはり、市民科を中心としたキャリア教育の中で行っていくというのも１つだと思いますし、その中で、例えばまちの人に学ぶ授業等で、まちの方、国内であっても実際に英語を駆使されている方、使っていらっしゃる方、または非常に英語が好きで、夢を持って活躍しようとされている方。そういった方からお話を聞いていくということも重要だと思います。また、学校図書館にも、そうしたさまざまな職業について知るための資料等もございますので、そうしたところで、まずは紹介していく、伝えていくということが重要であると考えます。"},{"i":187,"speaker":"高橋（し）委員","text":"本当に身近なところで、そういった、本当に大げさに英語を使う仕事みたいなのでなくてもあるのだというのを、やはり教えていってあげるといいと思うので、ぜひ、今お話があったようなところで進めていっていただきたいと思います。\n先ほどプログラミング教育のときに、ちょっと教育総合支援センター長にお答えいただいたのですけれども、企業のかかわり方で、聞き漏らしてしまったのですが、プログラミングの何に加盟している企業などにいろいろご協力していただいているのでしたか。"},{"i":188,"speaker":"大関教育総合支援センター長","text":"東京都教育委員会が、全都的に、プログラミング教育推進モデル授業を、今年度より２年間行うに当たって、そこに携わっていただく企業、プログラミング教育推進企業の企業体連盟というものを、東京都教育委員会が組織しております。そこに加盟していただいている企業です。"},{"i":189,"speaker":"高橋（し）委員","text":"そうすると、その中で品川区でやられていると、品川区にある、現状、今、品川区にかかわっている企業が多くなるのですか。"},{"i":190,"speaker":"大関教育総合支援センター長","text":"品川区だけではなく、東京都内の企業が加盟されておりまして、区内に本社がある企業だけではありません。ただ、そちらの連盟のほうには当然、今後も追加で加盟していくことは可能ですので、既に昨年、平成２９年度に、第二延山小学校に来ていただいたＩＴ系の企業は当時は未加盟でございましたので、今回、東京都のモデルを受けるに当たって加盟していただいたという経緯がございます。"},{"i":191,"speaker":"塚本委員長","text":"ほかにご発言はございませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":192,"speaker":"塚本委員長","text":"ご発言がないようですので、以上で所管事務調査を終了いたします。\n────────────────────────────────────────────\n３ その他\n(1) 所管質問について"},{"i":193,"speaker":"塚本委員長","text":"次に、予定表３ その他を行います。\nまず、(1)所管質問についてを議題に供します。\n昨日の委員会において、飯沼雅子委員より、今定例会の一般質問にかかわる所管質問の申し出がございました。質問項目は、藤原正則議員および南恵子議員の一般質問のうち、「待機児童対策について」の項目から、「待機児童ゼロの継続等について」と、藤原正則議員の一般質問のうち、「大井町の再開発について」の項目から、「ひろまち保育園の今後について」でございます。\nこれより所管質問を行いますが、申し出をした委員以外の方も議論に加わることができますので、よろしくお願いいたします。なお、本日の質問につきましては、文教委員会にかかわる項目についての所管質問でありますので、ご留意願います。\nそれでは改めまして、飯沼委員の所管質問について、本会議の質問の繰り返しにならないような形で質問をお願いします。"},{"i":194,"speaker":"飯沼委員","text":"委員長が全部まとめて言ってくださったので。"},{"i":195,"speaker":"塚本委員長","text":"質問としては、私の今申しあげたことでいいということですか。"},{"i":196,"speaker":"飯沼委員","text":"はい。"},{"i":197,"speaker":"塚本委員長","text":"では、答弁をお願いいたします。"},{"i":198,"speaker":"大澤保育支援課長","text":"それでは、待機児童とひろまち保育園についてご説明いたします。待機児童の見通しですが、現在平成３１年４月の申し込み数は前年比１.９％増の３,５５４人、入園数は２,９１２人と見込んでおります。不承諾者６４２人のうち、待機児童から除くとされる数の内訳は、認証保育所等、他の保育施設を利用される方が２８４人、既に認可保育園に在籍しており、転園を希望される方が１２４人、希望園が１園のみなど特定の園を希望される方が１５２人、求職活動を休止される方が３９人、育児休業を延長される方が４０人、合計で６３９人と予測しており、誤差を含み、ほぼゼロになると考えております。なお、待機児童から除く数は、平成２８年度から平成３０年度までの推移でございますが、７９３人、７９７人、６８０人となっており、平成３１年度については過去の傾向を参考に算出したものです。\n今後の開設ですが、品川区子ども・子育て支援事業計画の本年４月の改訂に伴い、新たな人口推計により保育施設の確保方策を算出しており、計画に沿って受け入れ拡大を行っていくことで、保育需要に応えてまいります。平成３２年度からは、新たなニーズ調査、人口推計による計画になりますので、引き続き計画に沿った開設を進めていくことで、待機児童ゼロを継続していけるものと見込んでおります。\n次に、ひろまち保育園ですが、ＪＲ大井町駅横にある、５年間の期間限定の公設民営保育園です。平成２８年４月に開園し、平成３３年３月までの運営を予定しております。現在、開園後、約２年半を経過しております。定員は３００人、対象は１歳児から５歳児まで。１０月１日現在の在園児は、約２７０人となっております。本会議の答弁でもございましたように、広町地区開発計画については\nＪＲ東日本と区の担当部署において調整しているところです。また、期間限定園でございますので、ひろまち保育園を閉園する際には在園児の受け入れ先の確保を行います。これは保育園のご案内にも記載したとおりです。"},{"i":199,"speaker":"塚本委員長","text":"答弁が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":200,"speaker":"飯沼委員","text":"ちょっと速かったので、数字が聞き取れないところもかなりあったのですけれども、１つには、待機児童ゼロが続くということで、今年度、厚生労働省の定義で、課長がおっしゃったように、認証保育園ほか、認可外でも入っている子どもたちや、転園を希望している人、あと特定の保育園しか希望しなかったり、求職中や育休中を除くと、今年は１９人でしたよね。それで、来年も、予測すると、さっき数字を書き取れなかったのですが、４人ですか。雑駁に言うと、多分、似たような数字だと思うのですけれども、この数をゼロと言ってしまっていいのでしょうか。私は本当に、一人ひとりのお子さんのことであり、大事なことだし、保育園に入れなかったら親御さんは仕事ができないわけですよね。そういった意味で、私は厳密に厚生労働省が言っているところだけが待機児童だとは絶対思わないのですけれども、そこの１９人に対しても、ほぼゼロで、この間ずっとゼロが続きますという言い方をしてしまっていいのかと私は違うと思うのです。ここが１人でも２人でも、やはりきちんと最後まで見なくてはいけないし、そのための手だては必要だと思うのですが、その点が１点。\nあともう一つは、私たちは認可保育園を希望して入れない子どもを待機児童と言っているのですが、そこが厚生労働省と、また品川区の考え方が違うと思うのです。それで、よくわからないのですが、一般にはよく隠れ待機児童みたいな表現をしていますけれども、申請して入園して、希望して入れなかった、今年は６４２人、この人たちを、結果的には待機児童ではないと除いていること自体、私は現実に目を向けない問題ではないかと思っているのです。１つは、認証保育園とか認可外保育園とか、保育料の助成はできましたけれども、やはりこの人たちは、ちゃんと国基準の認可保育園を希望しているのだといったら、やはり認可保育園の待機児童と考えるべきですよね。あと、転園希望とか、特定の保育園しか希望しないといっても、一人ひとりの家庭の状況を見たら、例えば兄弟姉妹関係があって、２カ所も３カ所も回っていて、１カ所、同じ保育園にしたいとか、勤務時間上、送り迎えができなくて、祖父母に迎えを頼むので、家の近くにしてほしいとか、通勤の夫婦の事情で、どこに預けないと送り迎えがうまくいかないとか、いろんな事情があるのです。そういう人たちを、全部こうやって待機児童から外している。また、職を求めていない人、中には、もうずっと落ちて落ちて、諦めて、４月１カ月に申請しなかっただけで待機児童から外されてしまうのです。こういう機械的なやり方をして、どんどん待機児童から外していくから、実態が見えてこない。だから、やっても、あと１９人ですと言って、来年、９３８人増やしますと言っていますよね。１９人なのに９３８人増やしても、なおかつ、また同じ状況が続くというところにおいて、機械的に外していってしまう、この問題。これ自体を見直していかなければいけないという、大もとの、今、２点を私はすごく思っているのですが、この点は品川区はどう考えているのでしょうか。"},{"i":201,"speaker":"大澤保育支援課長","text":"最初に、ゼロと言ってよいかというお尋ねですけれども、あくまでも実質的にはゼロですという見解でございまして、待機児童が１９人いましたけれども、同じ時期に０から２歳の認可保育園の定員枠は、７２人、空きがございましたので、そういう意味で、どうしても働けないような状況ということではないという認識のもとに、実質的にはゼロだと言っております。\n認可保育園、不承諾の人は全員、待機児童ではないかというお考えですけれども、やはり育休の延長や給付金申請のため、不承諾通知を得るために申し込みをされる方は一定数いらっしゃいまして、平成３０年４月の不承諾者のうち３割の方は１園しか希望していないということで、これは制度的な欠陥ということが、今、言われていますけれども、それにしても、やはりそれだけの方は、入園のご意思があって申し込みをされているとは見られないのではないかと認識してございます。\nそれから、待機児童の数え方ですけれども、国で決まっている以上、区として独自の数え方というのはできないものだと思っておりますので、国の考え方、定義に沿って数えていくしかないと思っております。"},{"i":202,"speaker":"飯沼委員","text":"すみません。育休のところで不承諾を待っている３割というのは、分母は何の３割か、もう一度教えていただきたいのと、品川区の育休を延長したいがために出している人というのは、一人ひとり当たって確認しているのでしょうか。入れたら職場に復帰するという人は絶対含まれていないのか、そこのところを教えてください。"},{"i":203,"speaker":"大澤保育支援課長","text":"不承諾者のうちの３割は、１園しか希望されていない方です。育休中の方の取り扱いについては、５月に申し込みをされた方は、入れればすぐに復帰したいという意思表示だと思いますので、その方たちは待機児童です。"},{"i":204,"speaker":"飯沼委員","text":"入れたら復帰するという。\n不承諾者の３割が１園のみということですね。だから、１園のみで、私は厚生労働省がやはり待機児童問題を捉えて、自治体の判断で、厚生労働省の基本的なところはあるのですけれども、そこの範囲の見方の問題を、やはり自治体の裁量で広げて考えられるという、厚生労働省の、これは通達というのか、保育所等利用待機児童数調査に関する検討のとりまとめというのが、平成２９年３月３０日に出ているところを見ると、保護者のための寄り添う支援についてということで、一律にばっちりと数字を当てはめて外していくものではないということで、例えば求職活動、仕事を求めている活動を休止している場合についても、一人ひとり、きちんと内容を聞いて、どうして求職を今、いっときやめているのかというところとか、特定保育等を希望している人に対しても、通勤時間や通勤経路を踏まえていろいろ判断すべきであるということを言ったり、あと、育休についても、課長は、５月に申し込んだ人だから、育休中でもすぐに復帰したい人は５月に申し込むだろうとおっしゃいましたけれども、必ずしもそうではないので、一人ひとりの置かれている状況をちゃんとチェックして、寄り添う支援をという求め方をしているのです。だから、一律にどんどん減らして待機児童数を少なく見せていくというのは、やはり厚生労働省ですら問題視しているという中身なので、国が決めているのに従ってやるというのは、ちょっと主体性がないと思うのと、ぜひ親御さんたちの状況をもうちょっときちんと把握して捉えてほしいと思っています。\nこの間の南委員の質問の中で、入園申込者数から入園可能数の見込みを引いて、残った６４２人がいたのですが、この中身というか、０・１・２歳の人数を教えてほしいのと、あと、入園申し込み、３,５５４人の中の０・１・２歳の希望の数、できたら数字を教えていただきたいと思います。なぜなら、来年、９３８人、拡大しますと、よく数は言われるのですが、この中で０・１・２歳というのは、大体、私たちは４割ぐらいだと思っているので、９３８人つくっても、４歳・５歳のところで当然空いてしまうので、ここの数字を持ち合わせていたら教えていただきたいと思います。"},{"i":205,"speaker":"大澤保育支援課長","text":"平成３１年度の予測数でございますが、０・１・２歳に限って言いますと、申し込み数が２,９５９人、入園者数が２,３４７人、従って不承諾数は６１２人と予測しております。なお、新規園の開設でございますけれども、０から２歳児の定員数は３８７人を予定しているところです。"},{"i":206,"speaker":"飯沼委員","text":"今の教えていただいた数字によると、０・１・２歳の来年の希望が、入れないお子さんが６１２人で、新規で入れる部分が３８７人ということなので、やはり、今年ほどではないですけれども、入れない子どもたちが出る、やはり、これの繰り返しをどう改善していくのかという立場にぜひ立っていただきたい。待機児童はゼロが続いていますという発言自体は、やはり実態に目を向けていないのではないかと思いますが、いかがでしょうか。終わりにします。今のだけ答えてください。"},{"i":207,"speaker":"大澤保育支援課長","text":"保育園の利用者数でございますけれども、二十数年先には必ず減少に転じるときが来ますので、そういった意味では、認証保育所等と既存の施設を活用して対応していくことが必要だと考えております。国や都の待機児童対策も、認可保育所で全てを充足するという考え方ではございません。区としましても、従前から総合的な待機児童対策として認可保育所の開設を中心にしてはございますけれども、その他の対策もあわせて進めてきたところでございます。子ども・子育て計画におきましても、総合的な対策での確保方策となってございますので、それに合わせて、今後も計画どおり進むように努力してまいります。"},{"i":208,"speaker":"飯沼委員","text":"ごめんなさい。最後と言ったのですが。"},{"i":209,"speaker":"塚本委員長","text":"同じ会派の方の所管質問でもあるので、簡潔に。では、これを本当に最後でお願いいたします。"},{"i":210,"speaker":"飯沼委員","text":"いろんな意見があるので、聞いていただきたいと思います。利用者の数が、いずれ減ると思いますが、私たちは、今、公立保育園などの定員オーバー、定員より１２０％近くも入れている部分を考えると、子どもが減っても、よい環境で育てる。今が必ずしもよいと思っていませんし、最低の国基準を緩和した認可外保育園でいいとも思っていないのです。だから、やはり量もですけれども、質の問題も追求していったら、保育園が余って仕方がないという時代は、私たちはやってこない。よほど人口が減らないとやってこないと思います。やはり、園庭もあるし、認証や認可外をよしとしてしまうと、外遊びのできない保育園ばかりを認めてしまう。これは、今の規制緩和の中の流れで行われていて、やはり子どもの育ちよりも財政面を重視した政治の流れの中にあるので、やはり子どもにとって最善の利益を求めていくという保育園が必要だと思いますので、ぜひ方向を、きちんと子どもが育つ、質の保てる方向に行ってほしいと、これは意見で終わります。"},{"i":211,"speaker":"塚本委員長","text":"では、以上で所管質問は終了いたします。"},{"i":212,"speaker":"南委員","text":"委員長。"},{"i":213,"speaker":"塚本委員長","text":"南委員、ご自身の一般質問ですし、再質問もされています。それをこの場でというのは、ちょっと控えていただきたい。"},{"i":214,"speaker":"南委員","text":"２回だけなので、簡潔に質問させていただきたいと思います。"},{"i":215,"speaker":"塚本委員長","text":"それはちょっと、やはり所管質問本来の意味がずれてきてしまうと思うのです。一般質問に対して、他の委員が質問するというのが本来の意味なので。"},{"i":216,"speaker":"南委員","text":"そう。他の委員がないですから。"},{"i":217,"speaker":"塚本委員長","text":"南委員ご自身の質問だから、これに関しては今回はご遠慮いただきたいと思います。"},{"i":218,"speaker":"南委員","text":"だって、ほかの議員もできるのだったら、みんなで議論しませんか。"},{"i":219,"speaker":"石田（し）委員","text":"質問します。これは毎回、待機児童の話になると、将来的に要は子どもの数は少なくなって、需要が減っていくのだという話が出てくるのですけれども、いろんな統計などを見たら、確かにそうなのかなと思う一方で、子育て支援というのは、すごくやろうとしているわけです。もっと子育てしやすい環境をつくっていこうと。人口減少が言われている中で、どうやって子どもたちを増やしていこうと言っているのだし、その支援というのもものすごくやっているのですけれども、そこの矛盾というのは、皆さん、保育支援課は感じているのでしょうか。待機児童を考えたときに、その辺はどういうふうに思っているのかというのが１点と、もう一点は、保育園に子どもを預けている家庭というのは、現在でも約半数ぐらいですよね。その方たち、今は半数が、例えば子どもが少なくなったからといって、逆に預ける家庭が増えた場合というのは、そこまで、保育園の入園される子どもの数というのは変わらなくなってくるのかと思うのですけども、その辺はどのように考えているのか、教えてください。待機児童対策に絡めてでいいです。"},{"i":220,"speaker":"大澤保育支援課長","text":"新規の申し込み人数ですけれども、平成２５年から平成２８年は、１１.４％から１６.６％と、５％以上の伸びがあったのですけれども、平成２８年から平成３０年は１７％前後で推移していて、もうここで高どまりではないかと思っています。ですので、品川区内の乳幼児人口が増えれば、もちろん入園希望者が増えますけれども、これまでのように、人口も増えて、申し込み率も増えてという、ダブルで増えていくような増加率ではないと思っています。かなり緩やかな伸びにはなってくると思いますので、そうなると、本来であれば、育休を２年ないし３年とってから復職したいと望まれている方もいらっしゃいますので、今までのように、保育園に入れないから、０歳で無理して復帰して保育園に入れるというようなことはなく、それぞれが自分のライフサイクルに合わせて保育園を利用できるようになるのが、一番望ましい形だと考えております。"},{"i":221,"speaker":"塚本委員長","text":"よろしいですか。"},{"i":222,"speaker":"石田（し）委員","text":"はい。"},{"i":223,"speaker":"塚本委員長","text":"以上で所管質問は終わりにします。\n────────────────────────────────────────────\n(2) 議会閉会中継続審査調査事項について"},{"i":224,"speaker":"塚本委員長","text":"次に、(2)議会閉会中継続審査調査事項についてでございますが、お手元の申出書（案）のとおりでよろしいですか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":225,"speaker":"塚本委員長","text":"それでは、この案のとおり申し出ます。\n────────────────────────────────────────────\n(3) 委員長報告について"},{"i":226,"speaker":"塚本委員長","text":"次に、(3)委員長報告についてでございます。\n昨日の議案審査の結果報告については、正副委員長にご一任いただけますでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":227,"speaker":"塚本委員長","text":"ありがとうございます。それでは、正副でまとめさせていただきます。\n────────────────────────────────────────────\n(4) その他"},{"i":228,"speaker":"塚本委員長","text":"次に、(4)その他で何かございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":229,"speaker":"塚本委員長","text":"ないようですので、以上でその他を終了いたします。\n以上で、本日の予定は全て終了いたしました。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ３時１８分閉会"}]});
